INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MiniCopter: Adventure Flight', 'All the fun of flying an RC helipopter without the fear of losing an eye! Engage in 42 missions in 7 different environments from a child’s bedroom, hospital, hotel room and more! Use your air cannon and lift suction to discover hidden areas and coins. Hone your flying skills to receive the highest amount of points possible in every stage. Engage in 42 missions in 7 different environments from a child’s bedroom, hospital, hotel room and more! Use your air cannon and lift suction to discover hidden areas and coins. Hone your flying skills to receive the highest amount of points possible in every stage.' FROM games WHERE igdb_id = 51064 ON CONFLICT (game_id, language_code) DO NOTHING;
