INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trolls de Troy: La Cité de la mort rose', 'Trolls de Troy : La Cité de la mort rose on PC is an french exclusive adventure game based on the comic book universe by Mourier and Arleston. You control two little trolls who must fight against humans determined to wipe out your race by sending you to a beautiful, pink world, the complete opposite of your own. With some point-and-click elements, the game maintains the humorous tone of the series.' FROM games WHERE igdb_id = 388737 ON CONFLICT (game_id, language_code) DO NOTHING;
