INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Apartment', 'The Apartment is a short RPG-Maker horror experience, about Joe Malcom, a resident of an apartment. After he receives books from his neighbour, after her husband commited suicide, strange things start to happen. Perhaps the same books offer an explaination on what is happening. A speciality of the game is, that everything happens in this one room apartment.' FROM games WHERE igdb_id = 281032 ON CONFLICT (game_id, language_code) DO NOTHING;
