INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'O.M.G. 26: Our Mini Games', 'O.M.G! Solve the mysteries of the spooky mansion and discover the treasures within! With a variety of mini-games that will test all of your senses and skills, you and your brave band of friends will overcome many obstacles and try to escape unscathed! This spook-tackular title is filled with fun and challenging mini-games that revolve around a haunted mansion theme. For a bit of fun and fright, this title is definitely the ticket for excitement! With over 25 mini-games that will have you fend off flying dishes, search for keys, escape from ginormous boulders and more, this title is perfect for on the go fun!' FROM games WHERE igdb_id = 110320 ON CONFLICT (game_id, language_code) DO NOTHING;
