INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('world-of-warcraft-the-burning-crusade-collectors-edition', 136995, '2007-01-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ye1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8i5q.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Warcraft: The Burning Crusade - Collector''s Edition', 'The Collector''s Edition for World of Warcraft: The Burning Crusade contains the following: - World of Warcraft: The Burning Crusade on both CD and DVD - 4 CD-ROMs in 4-CD Jewel Case and 1 DVD-ROM in a cardboard sleeve. - World of Warcraft: The Burning Crusade "Behind the Scenes" DVD. - With "more than two hours worth of developer interviews and commentary on all aspects of the creation of The Burning Crusade, as well as trailers and cinematics from the game, and even footage of panel discussions from BlizzCon". - The Art of World of Warcraft: The Burning Crusade Hardcover Art Book. - Hardcover coffee table book with exclusive concept art. - Exclusive In-Game Pet: Netherwhelp. - Two World of Warcraft Trading Card Game Starter Packs, plus Exclusive Cards. - A full-size color rulebook and 3 foil promo cards (which will be released in a future set in non-foil version) from the WoW TCG. - Map of Outland Mouse Pad. - World of Warcraft: The Burning Crusade Soundtrack. - Blizzard Product Catalog (Burning Crusade themed). - 2 World of Warcraft 10-day Guest Pass Keys.' FROM games WHERE igdb_id = 136995 ON CONFLICT (game_id, language_code) DO NOTHING;
