INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter: Mastering Magic', 'Harry Potter: Mastering Magic is a collection of mini games revolving around Potter''s main activity at Hogwarts (yes, that would be studying). The game has an interesting wrap-up where you need to play for a whole school year and pass your final exams. The game consists of the following mini games: Astronomy - memory game (connect stars to replicate a star configuration) History of Magic - quiz (Potter trivia) Divination - visual recognition puzzle (an object is twisted in a crystal ball, the player must choose the right object out of several similar ones) Transfiguration - a Tangram variant Potions - memory game (count ingredients) Care of Magical Creatures - common sense puzzle (feed the Thestral the right food) Charms - word game (explore a grid of letters and form a spell) Herbology - logic puzzle (grow plants by casting the right spells)' FROM games WHERE igdb_id = 266200 ON CONFLICT (game_id, language_code) DO NOTHING;
