INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inhabited Island: Prisoner of Power', 'Inhabited Island: Prisoner of Power is a linear, mission‑based first‑person shooter adapted from the Strugatsky brothers’ novel. Players control Maxim Kammerer through prison‑camp episodes and resistance missions on the planet Saraksh, using a multifunctional weapon with selectable fire modes to tackle human foes, hazards, and stationary electronic defenses. Levels mix outdoor areas, environmental dangers (mines, radioactive water), and occasional vehicle sections and stealthy diversions; between missions you can buy weapon mods, ammo, and healing items to prepare for the next operation.' FROM games WHERE igdb_id = 352354 ON CONFLICT (game_id, language_code) DO NOTHING;
