INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bug Mania', 'Bug Mania is a racing game featuring only Volkswagen Beetles. Its graphics are based on the 2 Fast Driver engine.  There are 2 playing modes: event and single race. In the event mode, the player has to race the 34 tracks available in order, unlocking them as the player beats them in first place.  In the single race mode the player can choose any of the 34 unlocked tracks and select any of the 8 unlocked cars available. The models are Standard, Cooler-Bug, Sand-Bug, Razor-Bug, Killer Bee, Cabrio Bug, Beach-Bug, Bat-Bug, with speeds ranging from 50 to 85 kph. Each car has also two color sets available to choose from.  The game is controlled with the keyboard and there are four camera angles available: two behind the car, a hood camera and a TV camera.' FROM games WHERE igdb_id = 140985 ON CONFLICT (game_id, language_code) DO NOTHING;
