INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Akasen Gairo: Shouwa 33 Nen no Hatsuyuki', 'After the war, there are several districts where people are allowed to open a brothel. The main character is Masayuki. He comes to one of the districts to look for his mother. But he can''t find her, and is at a loss what to do. Shizue, a brothel prostitute, takes care of him, and he begins to stay at her house.... What will he think when he meets his mother?' FROM games WHERE igdb_id = 153663 ON CONFLICT (game_id, language_code) DO NOTHING;
