INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rebirth RC', 'Originally named "RayCity", Rebirth RC brings back this game along with an amazing community. There is a huge map based on Seoul, Korea and you can do many missions in free roam such as taxi missions, delivery missions, chase missions, follow missions, and as well as Road Fighter missions. You can also participate in Limited Engine mode, Xtreme Race mode, and even race in lobbies. The game is currently in Thai language only.' FROM games WHERE igdb_id = 147808 ON CONFLICT (game_id, language_code) DO NOTHING;
