INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apathy: Midnight Collection - Vol. 1', 'Alternate retelling of the horror VN Gakkou de Atta Kowai Hanashi, comprised of three stories: Emi’s Murder Club Observation Diary, the main story, which chronicles the adventures of a psychopathic schoolgirl and her attempts not to be assassinated by the school’s Murder Club. The Following Dog, which revolves around the legend of a dog who will eat you if you look back on your journey. Scratches on the Pillars, a extremely short and completely linear story, yet very evocative and artistic.' FROM games WHERE igdb_id = 150056 ON CONFLICT (game_id, language_code) DO NOTHING;
