INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('real-football-2008-3d', 214825, '2007-10-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co550y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scijjm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real Football 2008 3D', 'Real Soccer 2008 3D is the third 3D game in the Real Football series but the first one that is fully 3D with polygonal player models and stadia. Next to the new graphics the game features similar content and mechanics to the 2D version. The view is still from the side line like in the previous 3D versions but it features a lateral camera that slightly rotates. The replay system is also more advanced with it being possible to rotate the camera and watch the action from different angles. The 3D version has the same game modes as the 2D version. This includes friendlies, cups and leagues as well as the new Road to 2008 and challenge modes. Road to 2008 involves qualifying for and competing in the Euro 2008 while the challenge mode is made up of a number of real life football scenarios where the player has to complete objectives. The Nintendo DS version has some differences from the mobile version. It has a multiplayer mode but lacks the challenge mode. It also adds some extra gameplay features that make us of the DS functionalities. It is possible to use the microphone to yell at referee and thereby influence his decisions while the stylus is used on the touch screen when taking penalties.' FROM games WHERE igdb_id = 214825 ON CONFLICT (game_id, language_code) DO NOTHING;
