INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BioShock: Limited Edition', 'Set in the steampunk Objectivist underwater dystopia of Rapture in the 1960''s, Bioshock is a first-person shooter wherein the player arms and genetically modifies themselves in order to survive against the city''s resident great minds-turned-maddened anomalies and aid a revolutionary leader named Atlas in overthrowing the city''s ruling despot, Andrew Ryan. The Limited Collector''s Edition includes: - Steelbook case for the Game - 6-inch (150 mm) Big Daddy figurine - DVD: "Making of" - CD: "The Rapture EP" (contains three tracks from the game remixed by Moby and Oscar the Punk: Beyond the Sea, God Bless the Child, Wild Little Sisters)' FROM games WHERE igdb_id = 142228 ON CONFLICT (game_id, language_code) DO NOTHING;
