INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Densha de Go! Shinkansen EX: Sanyou Shinkansen-hen', 'A spin-off of the Densha de Go! series, Shinkansen focuses on the titular high-speed rail line San''yō Shinkansen (through the entire route both ways, between Shin-Ōsaka and Hakata). The game was later ported to the Wii as Densha de Go! Shinkansen EX: Sanyoushinkansen-hen (loosely translated to "Go by Train! Shinkansen EX: Sanyou Shinkansen Edition") on March 1, 2007. This version features a new "Kids Mode" utilizing the Wii Remote''s motion control.' FROM games WHERE igdb_id = 146542 ON CONFLICT (game_id, language_code) DO NOTHING;
