INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sei-Romance Gakuen: Koi no Toki-meki Daisakusen', 'In the Romance Academy, the girls have all it takes to seduce the boys, notably a laser beam that keeps them at their beck and call! Once you meet a boy, click on his head to start seducing him, but watch out for the other girls, who will try and steal your conquests. Don’t let that happen! If you see another girl trying to chat up the same guy as you, click your mouse repeatedly to get the upper hand. Fill up all the hearts to become the best seducer in school!' FROM games WHERE igdb_id = 283538 ON CONFLICT (game_id, language_code) DO NOTHING;
