INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jelly Battle', 'In Jelly Battle you must outlast your opponents. Fighting on a grid, each turn you must select a new tile to jump to. If that tile is a special tile then you will perform whichever action tied to that tile. Call in airstrikes, shoot lasers and drop pianos. Make sure you''re the last to survive!' FROM games WHERE igdb_id = 237305 ON CONFLICT (game_id, language_code) DO NOTHING;
