INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Innocent Life: A Futuristic Harvest Moon - Special Edition', 'The game takes place on the relic-filled Heartflame Island which can be explored by walking or riding on a buggy. Players have the ability to explore the island''s ruins and even visit a volcano. All these areas have their own terrain and is said to resemble a tropical paradise but in order to explore all over the island the player must collect jewels and break the seal.' FROM games WHERE igdb_id = 43595 ON CONFLICT (game_id, language_code) DO NOTHING;
