INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Railfan: Taiwan High Speed Rail', 'Railfan: Taiwan High Speed Rail takes place in Taiwan, along the real-world Taiwan High Speed Rail line between Taipei in the North, and Zuoying to the South. Like the previous game in the series, Taiwan High Speed Rail uses full-HD footage of the rail line. The player is responsible for driving at the appropriate speeds and reaching stations on schedule. There are game modes which score the player based on total time spent on the route, energy used, or accuracy in stopping the train at stations. The game also includes a mode highlighting tourist spots along the route, with mentions of historic locations as well as sightseeing spots and restaurants.' FROM games WHERE igdb_id = 10742 ON CONFLICT (game_id, language_code) DO NOTHING;
