INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asian Dynamite', 'This game is a direct sequel to Dynamite Deka, meaning in its localised form, Asian Dynamite is a direct sequel to Die Hard Arcade, with the references to the movie franchise removed. The game has not been ported to home platforms, nor has it even seen a US release. It is extremely similar to Dynamite Cop in design, simply sporting an updated Asian aesthetic and replacing Jean Ivy and Eddie Brown with Caroline Powell and Jennifer Genuine, respectively. Caroline is the president''s daughter from the first game grown up.' FROM games WHERE igdb_id = 39645 ON CONFLICT (game_id, language_code) DO NOTHING;
