INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tobira no Densetsu: Kaze no Tsubasa', 'Lucia Maverick has worked as a maid in the remote village of Kast, home to many fleeing their pasts, for the last five years after the death of her parents. But her sick little sister, Anna, grows weaker by the day, and so Lucia plans to set out on a journey to Lestaria in hopes of finding employment as a Royal Guard on her fifteenth birthday, thereby securing funds for Anna''s treatment. But things do not go as planned, and the return of a past terror is just the beginning of a small yet massive adventure...' FROM games WHERE igdb_id = 143862 ON CONFLICT (game_id, language_code) DO NOTHING;
