INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider Riders: Battle for Arachna', 'Spider Riders: Battle for Arachna was a web browser RPG based on the anime series Spider Riders, itself an adaptation of a series of novels. The game''s Combat consisted of players rolling dice and using a deck of cards they assembled in turn-based battles. It featured a customizable avatar character and spider, 15 single-player missions, online play, and a Guild system, where players would align with one of four mentors to compete and amass the most points during recurring events.' FROM games WHERE igdb_id = 316801 ON CONFLICT (game_id, language_code) DO NOTHING;
