INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Initial D Arcade Stage 4', 'Initial D Arcade Stage 4 (also known as Initial D 4 in Europe and the US) is a 2007 arcade racing game based on the Initial D series. It is the fourth game in the Initial D Arcade Stage series. It was the first Initial D game to feature online battles via Sega''s ALL.net services exclusive to the Japanese release. A limited edition, called Initial D Arcade Stage 4 Kai, also exists. This is the last entry to have a full English localization.' FROM games WHERE igdb_id = 62308 ON CONFLICT (game_id, language_code) DO NOTHING;
