INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors Online', 'The game was originally announced for Microsoft Windows in 2004 as Shin Sangoku Musou BB (Dynasty Warriors Broadband), with a release in Japan in early 2006. The PS3 version was later confirmed, exclusive only to Japan, in 2010. The game''s name changed from Dynasty Warriors BB changed its name to Dynasty Warriors Online on Wednesday, November 28, 2007.' FROM games WHERE igdb_id = 72612 ON CONFLICT (game_id, language_code) DO NOTHING;
