INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'V tylu vraga 2: Bratya po oruzhiyu', 'A standalone World War II real-time action/strategy expansion built on the Faces of War engine, offering a focused single-player campaign that follows intense tactical combat with squad and vehicle control across varied battle scenarios on the Eastern Front. The game blends squad-level decision-making, destructible environments, and strategic positioning in historically inspired missions, while also featuring new multiplayer maps and modes for competitive and cooperative play.' FROM games WHERE igdb_id = 393302 ON CONFLICT (game_id, language_code) DO NOTHING;
