INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Katekyou Hitman Reborn!: Dream Hyper Battle!', 'Katekyou Hitman Reborn!: Dream Hyper Battle! covers the Kokuyo Arc, when Mukuro and his subordinates escape from the Vendicare Prison and are after Tsuna and his Guardians. It also covers the Varia Arc, when Xanxus is after the title of the Tenth Boss of the Vongola and hosts the Vongola Ring Battle Tradition.' FROM games WHERE igdb_id = 4949 ON CONFLICT (game_id, language_code) DO NOTHING;
