INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gekkou-no-carnevale', 137102, '2007-01-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fdh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8iid.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gekkou no Carnevale', 'The story is set in Belmonte Calabro in Italy. Belmonte is the city of filled with Automatas and boasts the biggest number of Automatas produced a year.  Automatas are androids. Mechanical beings created from nothing. Most Automatas can be easily distinguished from humans due to their robotic faces but there are the Antique Dolls, which looks exactly the same as humans with only their eyes giving away who they really are.  You start off as Romeo, a slack taxi driver who absolutely stinks at going around the city with his taxi. Or that’s what he looks like from the outside.  But the truth is, he’s a runaway werewolf from the Orma Rossa, the only remaining werewolf clan.  He lives together with Anna, an Antique doll he picked up from the dump after he left the Orma Rossa. She doesn’t have any memory of the past. So she’s living happily with Romeo.  But pleasant times never continue for long. Orma Rossa do not feel like ignoring Romeo any longer and the group called Luparia (the archnemesis of the werewolves), is moving behind in the shadows. Romeo will find himself surrounded by both new and old foes. This time, their target may not only be him…' FROM games WHERE igdb_id = 137102 ON CONFLICT (game_id, language_code) DO NOTHING;
