INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barbie as the Island Princess', 'Barbie as The Island Princess follows the storyline of the popular DVD launch in a fun party-style format. You''ll play as Rosella the shipwrecked princess who is raised by a "family" of animal friends and rescued by Prince Antonio from her tropical island. Through a series of mini-games featuring music and characters from the movie you will venture from Rosella''s island home to the Prince''s coastal castle in a fun-filled adventure!' FROM games WHERE igdb_id = 3309 ON CONFLICT (game_id, language_code) DO NOTHING;
