INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Floribella', 'Floribella is a platformer game released by Move Interactive in partnership with SIC, based on the second season of the Portuguese soap opera, Floribella. In this game, you can play as Floribella or Count Máximo and explore three different game scenarios, the Garden, the Mansion and the Palace. It features several missions and at the end of each mission, the player will have the opportunity to face super enemies.' FROM games WHERE igdb_id = 187868 ON CONFLICT (game_id, language_code) DO NOTHING;
