INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragonea', 'Dragonea is a free online text-based dragon breeding simulation game. Players take on the role of breeders responsible for caring for virtual dragons, from their hatching to their maturity. The game offers six dragon species, each with unique characteristics. Players begin by choosing the species, name, and gender of their first dragon, then manage its growth by ensuring its well-being through various activities and interactions. Dragons can also be bred together to create new species.' FROM games WHERE igdb_id = 326064 ON CONFLICT (game_id, language_code) DO NOTHING;
