INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tantei Kibukawa Ryousuke Jiken-tan: Vol. 6 - Tsuikou Saku Jiken', 'The 6th installment of the popular mystery game “Kibukawa Ryousuke Jiken-tan Series”! At the request of Detective Otonari, Ituna unravels a past serial murder case. Masao Ikuo is asked by a client at a detective agency to find someone. Two incidents that happened to two people. parallel and intersecting. What awaits at the end is a surprising truth.' FROM games WHERE igdb_id = 296408 ON CONFLICT (game_id, language_code) DO NOTHING;
