INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '101 Dino Pets: The Virtual Pet Game', 'Choose from over 101 cute, adorable dinos - or simply adopt them all! You''ll never be bored with so many new dino friends to groom, pamper, play with and love! Teach your dino to dance, jump, fly and more. Reward your pet with a treat after each trick! Enter your dino into pet shows and earn money to buy fun upgrades, including toys, food, furniture and more! Buy cute clothes and dress up your dinos in 3D! Zoom in, zoom out, tilt and rotate in real 3D. Watch your dino, up close and personal!' FROM games WHERE igdb_id = 52341 ON CONFLICT (game_id, language_code) DO NOTHING;
