INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('33-kvadratnykh-metra-voyna-s-sosedyami', 337520, '2007-03-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9ljg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvzy8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '33 kvadratnykh metra: Voyna s sosedyami', 'An arcade computer game developed by the Ukrainian studio Jam-Games and published by Novy Disk in 2007. It is based on the TV series of the same name. The player takes on the role of each of four family members as they visit retribution upon the very inhospitable locals in their new town. Each character infiltrates the home or workplace of a target, using a point-and-click interface to stage elaborate pranks using improvised materials found in the battle zone. Well-executed pranks can be replayed at dramatic camera angles, optimizing the humiliation of the target. Timing and stealth are crucial to set up your opponents downfall, as the player must remain out of the enemies'' field of vision to avoid getting caught. All stages can be replayed at the players'' leisure to achieve better times.' FROM games WHERE igdb_id = 337520 ON CONFLICT (game_id, language_code) DO NOTHING;
