INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('weird-colony', 288651, '2007-01-23', NULL, NULL, NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Weird Colony', 'Weird Colony is an online multiplayer game which players will choose a race, then build a city, join a community, and wage a long term war against players of opposing races. There are three races to choose from: Robot, Flan, and Scarecrow. Robots are the technological race (of course). Flans are the magical race, and Scarecrows are the dark race. Each race has their own unique structures and attacks. Robots specialize in combat against other players and against monsters. Flans specialize in monster growing and are strong against enemy bases. Scarecrows specialize in base defenses, such as powerful turrets and traps.' FROM games WHERE igdb_id = 288651 ON CONFLICT (game_id, language_code) DO NOTHING;
