INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luntik: Matematika dlya malishey', 'The project of the series "Luntik. Preparing for School", which includes five educational games for children aged 5-7. This is a children''s educational computer game about Luntik - a character from the cartoon of the same name. Traveling through a wonderful fairy-tale world with Luntik and his friends, little players will learn to perform basic arithmetic operations - add, subtract and compare numbers, as well as tell time on the clock. Fun mini-games and meetings with the heroes of their favorite cartoon in new funny situations await the little ones.' FROM games WHERE igdb_id = 337901 ON CONFLICT (game_id, language_code) DO NOTHING;
