INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ninja-no-gakko', 290402, '2007-09-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7vfm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr0w6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja no Gakko', 'Train without haste! A collection of mini-games set in a ninja school. Players become students of ninja schools and take various ninjutsu classes in a mini-game format to hone their skills. Ninja school is a three-year system. " Improve your ninjutsu skills in classes such as "the art of change", "the art of hiding", and "shuriken throwing" and challenge the promotion exam and graduation exam. Also, after graduating from ninja school, a complete "job history" is also prepared as a hit-and-run element. The game starts from the first grade. As a class, it is a flow to improve your grades while practicing mini-games and challenge the promotion exam. There is no limit to the number of classes, and you can take your favorite subjects as many times as you want, so let''s practice as much as you want, such as practicing the subjects you are not good at and updating the best score! Demonstrate the results of your training in the exam! The exam is to play mini-games in all classes in no particular order and in a row. If you meet a certain standard together with the results of the regular class, you will pass the exam. Please achieve excellent grades and aim for graduation. Includes a mini-game that requires concentration!! There are 5 types of mini-games. You can play a wide variety of mini-games, such as "Shuriken throwing" that aims at enemies that appear up, down, left, and right, and "the art of change" that memorizes the cry of frogs in order. If you advance, you will be able to take new classes, and the difficulty of the subjects so far will also increase!!' FROM games WHERE igdb_id = 290402 ON CONFLICT (game_id, language_code) DO NOTHING;
