INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider: Anniversary - Collectors Edition', 'Tomb Raider: Anniversary is a remake of the original Tomb Raider with a technically more advanced graphics engine. It has the same basic storyline, though some cutscenes and much of the dialogue within have been expanded or modified in other ways. Two disc collectors edition - Bonus materials include : - The Tomb Raider Story: A Ten Year Retrospective Documentary - Tomb Raider: Anniversary and Tomb Raider: Legend Exclusive Soundtrack mix - gallery of Tomb Raider artwork and collection of trailers from the past and present' FROM games WHERE igdb_id = 202972 ON CONFLICT (game_id, language_code) DO NOTHING;
