INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bikkuriman-daijiten', 269720, '2007-08-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7667.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bikkuriman Daijiten', 'Bikkuriman Daijiten is a Bikkuriman game released by 3 o''Clock for Nintendo DS in August 2007. Similar to the 1988 Bikkuriman Daijikai, the game is an (improved) encyclopedia of the Akuma vs. Tenshi Seal series, containing seals from all 31 series. In the beginning the seals are all black and white, but players can obtain points and use them to buy Bikkuriman Choco, where the seals can be obtained and later viewed in color. Depending of the seal, once obtained they will also have extra content unlocked, like extra information, their alternate versions from other products (like Bikkuriman Ice), and the ability to move foil cards (like Black Zeus) to see their colors. Points are earned in three ways: Once per day a certain amount is given to the player, by answering questions in the quiz mode, or trading duplicated and unwanted (becoming black and white again and locking bonus content if all are given) seals for 5-150 (depending of the seal) points each. It is also possible to trade seals with other players.' FROM games WHERE igdb_id = 269720 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 269720 AND p.igdb_id = 20 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('oriental-legend-2', 82753, '2007-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/dy3l0kmh2jxfshypdidl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc77sg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oriental Legend 2', 'Oriental Legend 2 follows up the original game by I.G.S. with another romp through Journey to the West. The original game''s five characters are joined by three newcomers: Er-Lang, Drakan, and Princess Iron Fan. Two more characters can be unlocked after completing the game once. Like the original game, this is a scrolling beat-em-up for up to four players. This time around, character growth is a major gameplay feature. Players earn experience for defeating enemies and level up, with underleveled characters much more likely to have trouble beating late-game bosses. There are three game modes. "Plot" features seven stages with a regular difficulty level designed for regular players. "Online Ranking" is a more challenging eight-stage mode which, when completed, provides the player with a code to input at the official website in order to share their codes on the online leaderboard. "Challenge Boss" is a boss rush that goes through all of the bosses in the game, with players challenged to get through in as little time as possible. This is the first game for the PGM2 to feature support for the hardware''s card reader accessory. By buying an IC card at their local arcade, players gain the ability to save and load their character''s progress, allowing them to keep their level growth and items between runs.' FROM games WHERE igdb_id = 82753 ON CONFLICT (game_id, language_code) DO NOTHING;
