INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TwinBee Da!!', 'A remake of the original Game Boy game that was included in the PSP compilation TwinBee Portable. It features all new full color graphics, new background music, and various new locations. The remake was developed by M2 and features music composed by Manabu Namiki, who produced an arrangement of the Game Boy version''s soundtrack by emulating the sound style of the Bubble System hardware that the original arcade version of TwinBee ran on.' FROM games WHERE igdb_id = 282567 ON CONFLICT (game_id, language_code) DO NOTHING;
