INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'UFO Stomper', 'The UFO Stomper by Triotech is a revolution in interactive coin-op gaming, featuring a patent pending, “shadow free” floor projection system to interact with! Players insert their credit then can choose from 10 different multiplayer games to enjoy, featuring funny aliens and many other original characters! This game supports 1 or 2 players and offer variety to keep replay value high; play games where you need to stomp on aliens or targets or there are games where players must avoid touching certain things with their feet. The UFO Stomper features a world’s first interactive floor with instant action feedback and “shadow-free” floor projection system that is accomplished through the use of two projection systems.' FROM games WHERE igdb_id = 348013 ON CONFLICT (game_id, language_code) DO NOTHING;
