INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jungo', 'Help Chase the Cheetah rescue his jungle friends in this unique and colorful puzzler. The villainous vulture Vargas has unleashed a shadowy spell and trapped all the animals in bright bubbles. Using cat-like reflexes and a keen eye for color, arrange the colored bubbles into matching groups to free the captive creatures.' FROM games WHERE igdb_id = 257391 ON CONFLICT (game_id, language_code) DO NOTHING;
