INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Quest for Aladdin''s Treasure', 'The Quest for Aladdin''s Treasure is an action adventure 3D puzzle game based on the tale from the book of One Thousand and One Nights. The player takes control of Aladdin and has to solve puzzles while traveling on his magical flying carpet from one location to another. Puzzles include slide puzzles, moving planks of different lengths on pillars and pushing blocks in gaps in the floor to reach the exit, among others.' FROM games WHERE igdb_id = 188142 ON CONFLICT (game_id, language_code) DO NOTHING;
