INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game de Demashita! Powerpuff Girls Z', 'Game de Demashita! Powerpuff Girls Z was developed by Infinity and published by Bandai for the Nintendo DS (now known as Bandai Namco) on June 14, 2007. It has board-game style gameplay similar to Mario Party and features Blossom, Bubbles and Buttercup competing with Mojo Jojo to get to the center of the board, competing in minigames along the way. The game received a Cero A rating in Japan which is the equivalent of an E rating in the United States.' FROM games WHERE igdb_id = 133826 ON CONFLICT (game_id, language_code) DO NOTHING;
