INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('death-note-kira-game', 22388, '2007-02-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8zz0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/snzesktka7sy1lxxnjp3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Note: Kira Game', 'A Death Note video game developed and published by Konami for the Nintendo DS, titled Death Note Kira Game (デスノート キラゲーム Desu Nōto Kira Gēmu?), was released on February 15, 2007. Kira Game is a strategy game where the player takes on the role of Kira or L. These are just titles, as any character can be Kira or L. The player will attempt to deduce who their enemy is (Kira will try to uncover L''s identity and vice versa). This will play out in three phases: investigation, where the player will discuss the case and clues with other characters; voting, where each member of the investigation team casts a vote on who they suspect is L or Kira based on the player''s performance in the previous phase; L/Kira, where the player can either focus their investigation on one member to see if they are Kira (L part) or force a member off of the team (Kira part).' FROM games WHERE igdb_id = 22388 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 22388 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
