INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DanceMela', 'Get danceMELA, India''s first Multiplayer Online Dancing Game. Dance with people from all over India while enjoying the latest Bollywood hits. Create your very own character, choose what they wear right from the hairstyle to the type of shoes. Meet, greet and chat with other players using the in-game Chat tool. danceMELA is easy to learn, fun to play and the best way to make new friends online. Get In, Get Dancing!' FROM games WHERE igdb_id = 346162 ON CONFLICT (game_id, language_code) DO NOTHING;
