INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fullmetal Alchemist: Trading Card Game', 'A completely accurate translation of the popular Fullmetal Alchemist trading card series by Press Pass, Inc (formerly JoyRide Entertainment), the Fullmetal Alchemist Trading Card Game brings the collectible strategy game to the Nintendo DS with nearly 500 cards, a variety of play modes, and extensive touch screen support. Featuring the most popular characters from one of the top-rated anime programs on Adult Swim, the Fullmetal Alchemist Trading Card Game allows you to battle against both AI-controlled opponents and friends via the Nintendo DS'' Wi-Fi capabilities. Earn new cards in Character mode, learn to play in Tutorial mode, or even build your ideal deck in Fantasy mode.' FROM games WHERE igdb_id = 47697 ON CONFLICT (game_id, language_code) DO NOTHING;
