INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wacky Zoo GP', 'Skid, jump and bump to first place with the help of the boosts, bombs, rockets & more! Blast your way around Wacky Town, bash your way around the Jungle tracks, and generally throw all you can grab at those who dare race ahead of you! Practice with the weapons in the Quick Races, get your name up in lights in the Time Trail records, and take on (or blow up!) the best to win the coveted trophies in the Tournaments to become top of the Wacky Zoo GP!' FROM games WHERE igdb_id = 66926 ON CONFLICT (game_id, language_code) DO NOTHING;
