INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godville', 'Godville is a massively-multiplayer zero-player game (ZPG). The gist of Godville is that it is a parody on everything from "typical" MMO games with their tedious level ups to internet memes and ordinary day to day things appealing to a wide audience.' FROM games WHERE igdb_id = 47002 ON CONFLICT (game_id, language_code) DO NOTHING;
