INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash of the Titans: Monster Edition', 'A special edition of Crash of the Titans that includes the game itself and comes with the following items: A Crash sticker set A removable Crash tattoo set A pencil case A mobile phone dangler A bonus DVD that includes interviews, trailers, game hints, etc... The Bonus DVD includes an interview with the developers, the trailer for the game, the trailer for The Legend of Spyro: The Eternal Night, hints and tips, cheat codes, and a link for exclusive bonuses in the Crash Village web site' FROM games WHERE igdb_id = 386044 ON CONFLICT (game_id, language_code) DO NOTHING;
