INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmare of the Webslinger', 'This game was available in Hasbro''s website. The game uses pictures of figures and toy Web-Shooters from Hasbro''s Spider-Man 3 toyline. It is a first-person-shooter style game where Spider-Man has to shoot his enemies with his webs and gain points. If he hits his own picture, he loses points instead.' FROM games WHERE igdb_id = 338785 ON CONFLICT (game_id, language_code) DO NOTHING;
