INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MechQuest', 'MechQuest is a FREE browser-based fantasy giant destructive war machine battle game. Sound fun? You bet! Heavily inspired by the art from every mecha & giant robot series ever created (and we are throwing in magic and laser swords too!) we will be putting a true ''Anything Goes'' build and battle ''Lunchbreak-sized'' game. Keep your holivids tuned in for more... *Bizzzzzzipwhip...kccccht!*' FROM games WHERE igdb_id = 78644 ON CONFLICT (game_id, language_code) DO NOTHING;
