INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rockman Tennis', 'Released in 2007, Rockman Tennis is a tennis game starring the cast of the Classic series! There are seven playable characters, including an unlockable X! Each character has their own special move that can be performed when its meter is filled. For example, Mega Man unleashes a powerful charge shot… while Shadow Man clones the ball (isn’t that cheating?). There are also four cups with varying court types. With multiple skill upgrades from Auto’s shop, this game has more depth than some may imagine!' FROM games WHERE igdb_id = 288142 ON CONFLICT (game_id, language_code) DO NOTHING;
