INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasia Sango 4', 'This is the fourth installment of the role-playing series of stand-alone games "Fantasy Three Kingdoms". The background of the story is set about ten years after the first generation. In addition to the latest developments in the series, it also inherits the battles of the Three Kingdoms and the unique world view of previous generations. Historical figures and military commanders also appeared in this generation.' FROM games WHERE igdb_id = 188657 ON CONFLICT (game_id, language_code) DO NOTHING;
