INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'An Untitled Story', 'In this Metroidvania game, players control an egg through a vast world, navigating many tricky platforming sections, defeating various bosses, finding upgrades to help them reach new locations, and collecting life-increasing hearts to survive exploring them. Also included is a multiplayer ''Heist Mode'' with gameplay very similar to capture-the-flag.' FROM games WHERE igdb_id = 72926 ON CONFLICT (game_id, language_code) DO NOTHING;
