INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('harry-potter-interactive-dvd-game-hogwarts-challenge', 266195, '2007-12-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co72dv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scoh8w.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter Interactive DVD Game: Hogwarts Challenge', 'Harry Potter Interactive DVD Game: Hogwarts Challenge is based on the first three Harry Potter films and allows the player to become a wizard-in-training at Hogwarts. It''s built around fourteen different mini games as well as short video clips from the movies. As a student the player has to take classes and each class is represented by a certain mini game that is played with the remote controller. The game is divided into three years and for each year the player has to complete three classes to reach the year-end challenge and then advance to the next year. Ultimately after all three years it''s possible to win tickets for the Quidditch World Cup. In addition to classes there are also additional mini-games called extracurricular activities that are unlocked as classes are completed. The game can be played both alone or against up to three other human players. Each player then chooses one of the four houses at Hogwarts and compete against each other in trying to get the highest score. It is possible to customize the difficulty for each player and there is also a mystery wand option where the difficulty level changes depending on how well the player is doing.' FROM games WHERE igdb_id = 266195 ON CONFLICT (game_id, language_code) DO NOTHING;
