INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pub Mania', 'Be quick on your feet as you serve customers in your own pub and open new pubs all around the UK! During happy hour, you alone will seat the customers, take their orders, and serve them. Pay attention to their preferences and react to their moods, because in Pub Mania, the customer is king! You can improve the place or improve the service. It’s up to you to turn it into the hottest spot in the city and make your dream a reality!' FROM games WHERE igdb_id = 325247 ON CONFLICT (game_id, language_code) DO NOTHING;
