INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Flash', 'Super Mario Flash (also known and abbreviated as SMF1) is the first of two online games developed by Pouetpu and released on pouetpu.pbworks.com before the creation of Pouetpu-games site. Super Mario Flash is entirely based off of the Nintendo game "Super Mario Bros.", and also combines several features of different games such "Super Mario Bros. 3". The main feature of this game is that includes a level editor so the players could make their own levels and share it on the forum/site so other players could test them and rate them.' FROM games WHERE igdb_id = 176865 ON CONFLICT (game_id, language_code) DO NOTHING;
