INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kekkaishi-kokubourou-no-kage', 61390, '2007-09-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3tge.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kekkaishi: Kokubourou no Kage', 'In Kekkaishi: Kokubourou no Kage players will play the role of the enchantment masters Momura Yoshimori and Yukumura Tokune who defend "Usen", fighting against the terrifying "monster". In order to guard the hero of "Wu Sen", you need to search for "Demon" in "Wu Sen Academy" under the night and use enchantment to destroy it. This process requires the four major steps of "square encirclement", "fixed foundation", "knot" and "destroy". First, after finding the enemy, quickly use the Wii remote control handle to draw the direction where the enchantment will be generated. This is the "square"; the "fixed base" is to specify the location of the enchantment. After completing the square, press the A button to proceed. Set the foundation", the longer the key is pressed, the larger the bounds will be after completion; the "knot" is the formation of an enchantment. After setting the enemy''s foundation, you can quickly raise your arm to complete the "knot" and close the set enemy. Even if you are successful in the enchantment, you can destroy the enemies in the enchantment by pressing the B button in the "knot" state, which is "destruction".' FROM games WHERE igdb_id = 61390 ON CONFLICT (game_id, language_code) DO NOTHING;
