INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cube', 'Set within in a 3D cubic world, The Cube is the newest puzzle addiction to hit the PSP & market. You’ll explore your way through suspended 3D platforms and mazes with themed sets of variables suited to that level. The Cube will provide the fun-factor that puzzle gamers have come to expect while adding action elements to broaden the PSP gamers'' experience.' FROM games WHERE igdb_id = 81499 ON CONFLICT (game_id, language_code) DO NOTHING;
