INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ouroboros', 'Ouroboros delves into themes of religious theology, history, archaeology, folklore, psychology, and mysticism, exploring the relationship between humanity’s inner spiritual power and the external world of lived experience. It features multi-layered map systems and unique combat mechanics to evoke a style blending reality and illusion, while aiming to express the philosophical theme of "humanity’s quest to explore inner spiritual visions.' FROM games WHERE igdb_id = 340969 ON CONFLICT (game_id, language_code) DO NOTHING;
