INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ultimate-street-football', 368804, '2007-04-13', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaigp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scz8r2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Street Football', 'Featuring the appearance of Barcelona striker Samuel Eto''o, this game takes football to the streets. As with other street sports games, Underground Street Soccer goes for a more arcade-oriented recreation of the sport. Doing tricks is therefore an important part of the game. When doing tricks your freestyle bar will be filled. When the freestyle bar has been filled, you can do a freestyle move. To perform a freestyle move you have to press certain buttons at certain time intervals. Three game modes are available. We have free match, where you play a single match with teams of your choice on one of the locations in the game, ranging from Brazil to France to Japan. Then we have the My Street mode, where you get to create your own team with your own players, and then play in a tournament against other teams from all over the world. After good performances you will be able to upgrade your team. The third mode is the Challenge mode, where you have to duel against another player. This is done by doing tricks in the same way as you perform freestyle moves in the game. When succeeding you will gain momentum over your opponent, and when you have full momentum you win the duel.' FROM games WHERE igdb_id = 368804 ON CONFLICT (game_id, language_code) DO NOTHING;
