INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panfu', 'Panfu was a massively multiplayer online role-playing game for children between the ages of 8 and 12. Each player had their own panda avatar that they could style. This avatar could then be used to walk around the virtual world, chat with other pandas, play games, and complete quests. It was eventually shut down in November 2016 due to financial difficulties caused by a lack of investors. However, fan-made versions of the game are still available.' FROM games WHERE igdb_id = 89508 ON CONFLICT (game_id, language_code) DO NOTHING;
