INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hitman: Blood Money Vegas', 'Enter the Dark underworld of organized crime as Agent 47, the ruthlessly efficient and professional Hitman. Your mission and objectives are issued by the ever present mission controller, DIANA. Can you achieve your objectives and dispatch your targets while remaining undetected? Shadows, Disguises and silent weapons are your best chances of getting through this isometric stealth adventure alive.' FROM games WHERE igdb_id = 125150 ON CONFLICT (game_id, language_code) DO NOTHING;
