INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spy-games-elevator-mission', 5205, '2007-11-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49x6.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spy Games: Elevator Mission', 'Enhanced 3D graphics – From sprites to polygons, this title has been faithfully recreated for the next-gen systems. Environments, levels, weapons and enemies will be familiar to fans of the series, while creating a new experience for those unfamiliar with the series. Level Design – Play through one enormous level, spread out through 40+ sections, minimizing load times and keeping the action continuous. Replay Value – Missions will never get stale as the key figures holding important documents, etc. are randomly assigned, giving the game almost infinite replay value. YOU’RE A SECRET AGENT TASKED WITH RECOVERING VITAL DOCUMENTS FROM THE ENEMY SYNDICATE. USE STRATEGY, STEALTH AND CUNNING TO ACCOMPLISH YOUR MISSION! GET IN! GET OUT! The classic gameplay of Elevator Mission is back with a new twist! Utilizing the unique control functions of the Nintendo Wii™, along with 3D graphics, this beloved title has been reborn for the next-generation consoles!' FROM games WHERE igdb_id = 5205 ON CONFLICT (game_id, language_code) DO NOTHING;
