INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shrek the Third', 'An action video game based from the third installment of the Shrek movie series. The Frog King has died and Shrek has inherited the throne. Since Shrek''s not a big fan of this idea, he and his friends journey to the Worcestershire academy to recruit Fiona''s cousin, Artie, for the job. Unfortunately, while he''s away the dastardly Prince Charming has big plans to take over the kingdom.' FROM games WHERE igdb_id = 200881 ON CONFLICT (game_id, language_code) DO NOTHING;
