INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Quest IV: Michibikareshi Mono-tachi', 'Embark on a journey to explore the land, seas and skies of the Dragon Quest universe in this grand entry from the Zenithia Trilogy. Soon to follow are Dragon Quest V: Hand of the Heavenly Bride and Dragon Quest VI: Realms of Reverie. Indulge in the colorful Dragon Quest world created by Yuji Horii, combined with the charming characters and monsters designed by Akira Toriyama and memorable soundtrack from famed composer Koichi Sugiyama to create an unforgettable gaming experience. Experience the world of Dragon Quest through the perspectives of multiple characters with a unique, chapter-driven storyline while you journey through a beautifully rendered 3D world, with dynamic dual screen presentation and newly animated monsters. The original Japanese version has all of the original content not present in the localizations.' FROM games WHERE igdb_id = 271211 ON CONFLICT (game_id, language_code) DO NOTHING;
