INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('astro-avenger-ii--1', 51211, '2007-07-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9a2b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scv20o.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astro Avenger II', 'In the decade since the Global Political Crisis, mankind has entered its second golden age planning to expand the man’s presence further in the Galaxy. But all the plans for the prosperous future crashed with the abrupt appearance of the hostile alien fleet destroying everything on its way. Humans found themselves on the verge of extinction and endeavored to resist the enemy. But all the attempts would have been vain had it never occurred to them to find and assemble the secret weapon which might reverse the flow of war to their favor. Astro Avenger 2 is a stunning comeback of the classic space scroller that lifts up the level of action, dynamics and drive in modern arcades. The detailed setting along with spectacular graphics abundant with modern visual effects and atmospheric futuristic soundtrack in the Hollywood style will not leave you indifferent and challenge your reaction and stamina by rash action operations in five immense worlds. There are 50 levels in 5 different worlds, 35 kinds of units and 15 types of weapons available in Astro Avenger 2. The gameplay, as the genre implies, represents a series of action operations the goal of which is to find all the pieces of the secret weapon which will reverse the flow of the war. Destroying alien ships the player collects plazma (the substance that the assembled secret weapon operates on) which can be further exchanged for new types of weapons or details for the ship comprehensive modernization in the nearest space-shop.' FROM games WHERE igdb_id = 51211 ON CONFLICT (game_id, language_code) DO NOTHING;
