INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peter Flat''s Inflatable Adventures', 'Peter Flat`s Inflatable Adventures is a quirky game of social satire featuring 50 awesome adventures. Newly recruited by the Corporate Corporation, Peter Flat must go through vigorous training to prove himself to the company. Transform Peter Flats 2D world into 3D while evading attacks from corporate rivals and the occasional 2D purist, hell-bent on keeping the world just the way it is.' FROM games WHERE igdb_id = 356997 ON CONFLICT (game_id, language_code) DO NOTHING;
