INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fiesta', 'A free MMORPG developed by the Korean company Ons On Soft. It is hosted for the North American market by Outspark and by gamigo for the EU territories. Experience the fantastic free2play Anime MMORPG Fiesta Online and dive into the magical world of Isya. Fight together with your friends and save the world of Fiesta Online while you enjoy exciting quests that will develop your character according to your wishes and find many new friends. Fiesta Online offers you as a free2play Anime MMORPG not only an active and friendly community but also many daily challenges.' FROM games WHERE igdb_id = 51217 ON CONFLICT (game_id, language_code) DO NOTHING;
