INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Manic Panic Ghosts', 'Manic Panic Ghosts, known as Poka Suka Ghost! It''s a Boo Bash! in Japan, is an arcade game released by Sega for Sega NAOMI arcade hardware in 2007. It can be seen as a hybrid between light-gun and "whack-a-mole" games, relying on magic hammer wands which players wave in the air (similar to Wii remotes). It has so far received no home ports.' FROM games WHERE igdb_id = 97676 ON CONFLICT (game_id, language_code) DO NOTHING;
