INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightmares: The Adventures – Broken Bone’s Complaint', 'Victor is a young boy haunted by terrifying nightmares. In this first episode, he must face his fear of the dentist — in the form of a monstrous creature named Dr. Broken Bone. Help Victor explore a surreal, spooky dream world, solve puzzles, and confront the source of his fear to escape the nightmare.' FROM games WHERE igdb_id = 360037 ON CONFLICT (game_id, language_code) DO NOTHING;
