INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farm Vet', 'You''re in charge of dozens of barnyard critters. Diagnose and treat their ailments using more than 30 realistic vet tools. It''s your job to take care of and nurture all the animals! Ride around the farm while treating 60 medical problems. Play 5 different minigames on your way to becoming the Head Vet. Treat, feed and pamper horses, calves, bunnies, ducks, sheep, chickens and more! With 3 levels of difficulty, Farm Vet is perfect for animal lovers and budding vets of all ages!' FROM games WHERE igdb_id = 357386 ON CONFLICT (game_id, language_code) DO NOTHING;
