INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rayman Kart', 'Rayman kart is a karting game developed by gameloft and released in 2007 featuring 8 courses to race on included within 3 different cups, the courses being: Dreamy Forest, Rockslide Race, Sanctuary of Fire, Frozen Highway, Shipwreck Track, Murky Swamp, Moonlight Pass and Rabbid Battlefield, The cups being Bronze, Silver and Gold. The game also included many popular characters from the rayman and Rabbids series, those being: Rayman, Globox, Teensie King, Razorbeard, Hoodblaster and Mr Rabbid' FROM games WHERE igdb_id = 61091 ON CONFLICT (game_id, language_code) DO NOTHING;
