INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fate/Stay Night: Réalta Nua', 'The complicated threads in Fate/Stay Night unravel in Réalta Nua. The series tells some of the most bloody and brutal love stories ever. The three heroines, Saber, Rin, and Sakura, each have a tale to tell, and depending on which path Emiya Shirou takes, he can either become the savior who ends the Holy Grail Wars for good or become another heroic spirit bound to be called out when the flames of war start again.' FROM games WHERE igdb_id = 146062 ON CONFLICT (game_id, language_code) DO NOTHING;
