INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alien Hominid 360', 'They''ve got your spaceship, so blow up anything in your path to get it back. Completely hand-drawn high-definition graphics coupled with old-school game play results in ultimate mayhem. This addictive, side-scrolling shooter features cute, quirky humor and adjustable cartoon gore. Alien Hominid HD features jump-in-anytime multiplayer action, immersive environments, award-winning bosses, and over 30 fashionable hats. This 2-D console experience comes jam-packed with seven mini-games, including several four-player party games. All You Can Eat, Neutron Ball, and PDA Games will keep the party going for hours on end.' FROM games WHERE igdb_id = 314895 ON CONFLICT (game_id, language_code) DO NOTHING;
