INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('koihime-musou-a-heart-throbbing-maidenly-romance-of-the-three-kingdoms', 23437, '2007-02-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9zl4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxjol.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Koihime Musou: A Heart throbbing, Maidenly Romance of the Three Kingdoms', 'Timeslip!? Kazuto went out to catch a thief that had broken into the local Chinese history museum late one night. But after a sudden confrontation with the thief, he finds himself absorbed in a white light only to awaken in a wasteland. What''s happened!? He is surrounded by three bandits. They try and steal his school uniform, but when he refuses to let them take it they attack. Just when he thinks he is about to be killed, a girl appears in front of him. She attacks the bandits with a spear of some kind and forces them to flee. "My name is Kan''u, My Lord. As the Messenger from Heaven please stand with me to help bring peace to this country at war."' FROM games WHERE igdb_id = 23437 ON CONFLICT (game_id, language_code) DO NOTHING;
