INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hannah-montana-one-in-a-million', 220093, '2007-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5f85.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4niz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hannah Montana: One in a Million', 'Hannah Montana: One in a Million was a Plug It In & Play TV Game released by Jakks Pacific and developed by HotGen in 2007 and re-issued in 2012. The controller contains four games: In "Lilly Boarding", you’ll have to guide Lilly through the city while she’s on her skateboard. You can jump and perform tricks to avoid obstacles and collect stars. The goal is to reach the end of the stage in the shortest time possible while collecting as many stars as you can. There are 5 stages in total, including the city in three slightly different versions, the pier, and the parking lot. In Photo Frenzy, Hannah Montana has to throw autographed photos to her fans while walking around the neighborhood. The fans are hiding everywhere, so you have to be quick. There are 3 stages in total. In Mannequin’s World, Hannah has to choose outfits for her concerts. On the screen, there are 15 outfits, and she gives you a description of what she wants. You must eliminate all the ones that don’t match until only one is left. There are 10 stages in total. In Mall Mayhem, you have to accompany Miley (and later Hannah) to the mall to take care of various tasks, such as reaching a store to sign autographs or dealing with bullies. An arrow shows where you need to go, and you must reach the destination before time runs out. Fans will try to stop you and make you lose time. There are 8 stages in total.' FROM games WHERE igdb_id = 220093 ON CONFLICT (game_id, language_code) DO NOTHING;
