INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic RPG: Episode 7', 'A multi-level RPG-style fighting game. It is really hard, but is very rewarding if you beat the opponent in each level - the game contains a movie that runs between the levels. Passwords are issued for each level so that you can skip them the next time you play if you wish.' FROM games WHERE igdb_id = 273562 ON CONFLICT (game_id, language_code) DO NOTHING;
