INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anika''s Odyssey', 'Anika''s Odyssey is an adventure that will take you deep into a lush and enchanted land. Author Comments: Anika''s Odyssey is a magical adventure deep into a lush and enchanted land. Break away from reality to enter a mystical world inspired by Aotearoa, New Zealand, as you meet the curious spirits and exotic creatures that inhabit this wondrous wilderness. Anika''s Odyssey is an enchanting point-and-click adventure game, full of a surprises and charm. Help Anika explore her colorful landscape as she journeys to reclaim her beloved friend.' FROM games WHERE igdb_id = 326755 ON CONFLICT (game_id, language_code) DO NOTHING;
