INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gun Star', 'Doujin game of the comedy slice-of-life series LuckyStar... with guns! GunStar takes the player in a series of side-scrolling levels blasting everything in sight, but unlike most side-scrolling shooting games GunStar aims for an FPS experience in 2D with WASD movement and mouse aiming, even emulating weapon recoil.' FROM games WHERE igdb_id = 208495 ON CONFLICT (game_id, language_code) DO NOTHING;
