INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RIP 2: Strike Back', 'Your favorite antiheroes are here to strike back with another score to settle. Death, Halloween and Rock-N-Roll... each character has his own strengths and skills, so pick one and start shooting. In Story Mode, you''ll fight through 60 furious levels using an arsenal of upgradeable weapons, tanks, helicopters and turrets or for a quick adrenaline fix, play Rush Mode and see how long you can last.' FROM games WHERE igdb_id = 28922 ON CONFLICT (game_id, language_code) DO NOTHING;
