INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster Hunter Frontier Online', 'Monster Hunter Frontier is an online MMORPG on the PC and Xbox 360 with a great amount of new weapons, quests, armor, and monsters. The game will continue to expand with new content added through patches. There is currently a Japanese, Korean and Chinese (Taiwan and Macau) version of Frontier. The game has a built-in IP blocker that prevents IP addresses outside of Japan from connecting to the server, but it is still possible for residents in other countries to connect. The Korean Frontier requires a KSSN (Korean Social Security Number) in order to play but it does not carry the same monthly fee as the Japanese version.' FROM games WHERE igdb_id = 7075 ON CONFLICT (game_id, language_code) DO NOTHING;
