INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Scenario', 'Last Scenario is an RPG with turn based battles. The party for battles can contain up to four members. Other than physically attacking and using items in battles players can also use magic in the form of Spellcards. There is also a mingame called Hex that can be played against certain people throughout the world. Hex is a card battle type game played on a hexagonal grid.' FROM games WHERE igdb_id = 124549 ON CONFLICT (game_id, language_code) DO NOTHING;
