INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('freakout-extreme-freeride', 17493, '2007-03-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3zxh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arsjw.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FreakOut: Extreme Freeride', 'The steepest slopes, thrilling stunts and dangerous action provide a most excellent skiing experience. At an altitude of 2000 metres, far away from civilization, in a battle between you and nature. Who rides the craziest track, where does the next jump lead to; speed, tricks or staying upright - Only those who are willing to push their own boundaries will experience the ultimate adrenaline rush! For the first time the player gets the opportunity to go off-piste with his skiers without being cramped by unrealistic barriers. Stylish jumps, no rules, extreme speed, off-piste, crazy stunts – that’s in! No barriers to prevent the player from feeling the real freedom of fresh powder snow while screaming down mountainsides with only their nerve to hold them back.' FROM games WHERE igdb_id = 17493 ON CONFLICT (game_id, language_code) DO NOTHING;
