INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Link''s Journey Deluxe', 'The Legend of Zelda: Link''s Journey Deluxe is a fan game of The Legend of Zelda by Tropical Bird. It''s story line is heavily inspired by Ocarina of Time, with many places being revisited. The game became somewhat infamous for it''s poor quality, due to the fact that it was the first game by the developer.' FROM games WHERE igdb_id = 241229 ON CONFLICT (game_id, language_code) DO NOTHING;
