INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Shop', 'You have more power in your index finger than you realize! Put it to use in Magic Shop, a charming new game in which you create artifacts by clicking on groups of matching elements. As customers place their orders, you must race to create the items they want. Not to worry, though. You can use spells that will help you collect the elements you need. As simple as tapping your mouse and as beautiful as a spring day, Magic Shop will charm you from the moment you begin playing!' FROM games WHERE igdb_id = 186122 ON CONFLICT (game_id, language_code) DO NOTHING;
