INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'N3wton', 'As the name suggests, N3wton is based on the premise of Newton''s 3rd Law - For every action there is an equal and opposite reaction. This rule governs your character throughout the game. Each of the 25 levels requires you to hit the enemy off the edge of the stage.' FROM games WHERE igdb_id = 262026 ON CONFLICT (game_id, language_code) DO NOTHING;
