INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gundam Battle Chronicle', 'Gundam Battle Chronicle is the sequel to Gundam Battle Royale and Gundam Battles series. It features over 140 Mobile units including the 80 units in Gundam Battle Royale and improved the multi-player gaming system so that the single-player missions could be played in multi-player''s mission mode. New additional missions are from Stardust Memory, and MSs from Gundam ZZ, Gundam Sentinel, and Char''s Counterattack.' FROM games WHERE igdb_id = 66596 ON CONFLICT (game_id, language_code) DO NOTHING;
