INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nodame Cantabile', 'Based on the manga series, Nodame Cantabile is a music/rhythm game where you lead a group of misfit musicians in an orchestra. You use the stylus to tap the screen in beat with the song, playing the part of the conductor Chiaki. The game features classical pieces from the anime series, as well as the Puri Gorota March! Nodame Cantabile has likely been inspired by Nintendo''s popular Nintendo DS Ouendan/Elite Beat Agents series. You have the scene playing out on the top screen and you hit moving notes on the bottom screen.' FROM games WHERE igdb_id = 64313 ON CONFLICT (game_id, language_code) DO NOTHING;
