INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Countdown 3: The Mind', 'Countdown 3 - The Mind is the third of a trilogy of text adventure games released as a prequel, of sorts, to 6 Days a Sacrifice. Many of the events depicted expand on events in Trilby''s Notes or 6 Days a Sacrifice. The year is 2386. You are an unnamed delivery man. You were given a parcel and a wad of cash as thick as your thumb by a bald man in tattered red robes. All you need to do is deliver the parcel to the occupant in cell 105 of the New Delhi Mental Hospital. Don''t let the guards see you.' FROM games WHERE igdb_id = 229149 ON CONFLICT (game_id, language_code) DO NOTHING;
