INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apathy: Gakkou de Atta Kowai Hanashi - Visual Novel Version', 'Sakagami Shuuichi, a member of the school newspaper, is asked to gather information about the school''s seven mysteries. He meets with six other students after school to listen to their stories. This game is a visual novel adaption of the two novels "Gakkou de Atta Kowai Hanashi" written by Iijima Takeo. It features the novels'' content with no branches, and an additional scenario called "Emi-chan no Sakagami-kun Kansatsu Nikki" (Emi-chan''s Sakagami Observation Diary).' FROM games WHERE igdb_id = 210818 ON CONFLICT (game_id, language_code) DO NOTHING;
