INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shakugan no Shana DS', 'Shakugan no Shana DS is the Nintendo DS port of the Playstation 2 game. It was released on March 29, 2007. The Nintendo DS version adds onto the PS2 version with the addition of an image gallery that allows the player to see what Shana and Kazumi Yoshida look like in different clothes and a battle mode that lets the player fight against the computer with a character other than Shana.' FROM games WHERE igdb_id = 123413 ON CONFLICT (game_id, language_code) DO NOTHING;
