INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neopets: Codestone Quest', 'Neopets: Codestone Quest propels you into a classic conflict between good and evil in the fantasy world of Neopia. The alchemist Oswoc needs codestones to activate a mysterious and powerful spell, and you must travel to seven fantastic Faerie Rings to collect them. Trouble is brewing, though, as the evil Balthazar is kidnapping faeries in record numbers. Free the faeries, collect codestones, and save the day in this all-new, exciting Neopets adventure.' FROM games WHERE igdb_id = 210104 ON CONFLICT (game_id, language_code) DO NOTHING;
