INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Megami Tensei QIX: Persona 3', 'Megami Tensei QIX: Persona 3 (女神転生QIX ペルソナ3) is a Persona 3-themed puzzle game developed for mobile phones. It was offered through the Atlus and Bbmf mobile telephone site called Megaten α starting on April 27, 2007. It functions similarly to the game it is titled after. Players complete levels by capturing at least 80% of the board. Enemies appear as Shadows and artwork and music from the original game appear.' FROM games WHERE igdb_id = 289392 ON CONFLICT (game_id, language_code) DO NOTHING;
