INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Go! Sports Ski', 'Go! Sports Ski is a skiing simulator that harnesses the SIXAXIS wireless controller to twist, turn and pull off tricks. The easy and intuitive motion control allows you to fly down visually stunning slopes right out of the gate. Supporting various single player modes, including slalom racing, a split-screen versus mode and several online battle modes, Go Sports Ski features two distinct courses.' FROM games WHERE igdb_id = 72936 ON CONFLICT (game_id, language_code) DO NOTHING;
