INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moonshine', 'This is the story of the unnamed protagonist — who finds himself suddenly without a means to support himself due to factors completely outside his control. This is the story of an entire generation — that finds itself attempting to navigate the treacherous abyss that lies in between childhood and true adulthood. This is the story of a nation — that finds itself struggling to come to terms with a lost decade and a rapidly-changing social climate. This is a story of these things and more. This is a story of us all.' FROM games WHERE igdb_id = 144799 ON CONFLICT (game_id, language_code) DO NOTHING;
