INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hoshigami: Ruining Blue Earth Remix', 'Experience the world of Hoshigami like never before, with a brand new character, missions, music, character art, as well as a new localization. Select from three different difficulty levels and tailor the game to your skill. Immerse yourself in battle with an enhanced user interface, and issue strategic commands quickly and efficiently with a revised, streamlined interface and optional stylus control.' FROM games WHERE igdb_id = 47717 ON CONFLICT (game_id, language_code) DO NOTHING;
