INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Line Game', 'After an early 3-level demo released on February 20th, 2007 via Digg became viral, this full release was published on AlbinoBlacksheep. In this game you have to guide the line through the pulsating red maze to the end with the mouse or keyboard. It’s simple but stupidly addictive. 8 levels, online highscores, and a mouse mode.' FROM games WHERE igdb_id = 262018 ON CONFLICT (game_id, language_code) DO NOTHING;
