INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Submachine 4: The Lab', 'Submachine. The game in which with every puzzle solved, every chapter finished you fall deeper and deeper into mystery. Fourth chapter takes us to the heart of the submachine, the place where all questions will be finally answered. Or were finally answered. Once again it’s time to ask youself – is it possible that you’re too late?' FROM games WHERE igdb_id = 129549 ON CONFLICT (game_id, language_code) DO NOTHING;
