INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Excit', 'Excit is the best safe for workspace puzzle game ever. You''re trapped in a spreadsheet and you need to escape the 30 levels using the cursor keys without sliding of the screen. Excit was created in the year 2005 as a viral marketing game for the German business software company MIS AG. In 2007, after the company dissolved, the game was released on the Internet for the first time.' FROM games WHERE igdb_id = 261087 ON CONFLICT (game_id, language_code) DO NOTHING;
