INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Powerslide', 'Powerslide is a Super FX supported game that was also in development for the Jaguar and 3DO. It was being developed by Elite, an English game company. According to Steve Wilcox of Elite, the game was cancelled because the cost of producing cartridges for the game was too high to make a return on the costs of software development.' FROM games WHERE igdb_id = 214976 ON CONFLICT (game_id, language_code) DO NOTHING;
