INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anata dake no Private Lesson: DS de Hajimeru Tipness no Yoga', 'DS:Style is a series of educational software products for the Nintendo DS console. The motto for the series is "The fun of games, the joy of learning". The game contains quizzes and interactive minigames to test the player''s knowledge. The series was perceived when it launched as an attempt by Square Enix to break into a new market, that of "non-traditional gamers". Several of the products were named after other non-software products including this game, translated "Tipness Yoga DS: Private Lesson Only For You" and named after the Japanese Tipness yoga studio chain.' FROM games WHERE igdb_id = 269550 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 269550 AND p.igdb_id = 20 ON CONFLICT DO NOTHING;
