INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Interactive Storybook DS: Series 2', 'Full of gaming goodness and positive fairy tales, this title immerses both the parent and the child into the world of skill building, learning, reading and having fun! Bringing different generations together like never before, Interactive Storybook DS aims to bring loved ones together to share, to grow and to prosper.' FROM games WHERE igdb_id = 123234 ON CONFLICT (game_id, language_code) DO NOTHING;
