INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('katamari-damacy-mobile', 243426, '2007-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6bma.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sclvbm.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Katamari Damacy Mobile', 'Katamari Damacy Mobile (塊魂モバイル, Katamari Damashii Mobairu, lit. "Clump Spirit Mobile") is a video game developed by Namco Bandaifor the Mitsubishi P904i series of mobile phones for NTT DoCoMo. It was released in June 2007 in Japan. It is a spin-off of the "Katamari Series", the second game on a portable system and the third game produced without the involvement of series creator Keita Takahashi. This version of the game uses a unique method of control, by making use of a software technology called GestureTek EyeMobile to make phones capable of detecting vibration via the built in camera on the P904i. The player is able to move the katamari ball forward, backwards, left and right by merely tilting the phone. There are also traditional controls as an option to the default motion controls. Katamari Damacy Mobile will come pre-installed on P904i model phones. Other phone models need to download the game through the Namco Games channel.' FROM games WHERE igdb_id = 243426 ON CONFLICT (game_id, language_code) DO NOTHING;
