INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elevators Amiss', 'In Elevators Amiss you are a maid working in a hotel gone crazy! Normally the night shift is pretty uneventful, but tonight the hotel''s elevators have taken on a life of their own! You need to get to the top of the hotel, but the elevators are simply not an option. To get to the top floor you will need to race along each floor of the building to the stairs while avoiding the out-of-control elevators! And when you do reach the top, you''re work isn''t done as you need to tackle the next hotel, also suffering the same problem!' FROM games WHERE igdb_id = 57580 ON CONFLICT (game_id, language_code) DO NOTHING;
