INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fall Down', 'Fall Down pits the ever-opposed forces of Red and Blue against each other in an ultimate battle to capture scrolling platforms! The first player to fall past a platform captures it and scores a point. Taking time to collect power-ups can give some advantage, but taking too long only results in death at the top of the screen. Watch out, because as you progress, the platforms slowly accelerates!' FROM games WHERE igdb_id = 40791 ON CONFLICT (game_id, language_code) DO NOTHING;
