INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'New Eitango Target 1900 DS', 'New Eitango Target 1900 DS is an educational English language learning game based on the Eitango Target series of books by Obunsha. These books teach a common set of English words in order to help students pass the TOEIC English language proficiency test. This game, specifically, is based on the Eitango Target 1900 book which teaches 1900 common English words.' FROM games WHERE igdb_id = 186732 ON CONFLICT (game_id, language_code) DO NOTHING;
