INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heroes: The Official Mobile Game', 'Join Hiro, Niki, Peter and more in the official, exclusive game of TV''s most talked-about series, Heroes, and experience the show''s mind-bending universe on your mobile phone. Relive the series'' thrills by entering an epic game that chronicles the lives of ordinary people who discover they possess extraordinary abilities - and an ultimate destiny to save the world! Experience the excitement of super-human abilities as you sneak into places unnoticed, save lives and fight enemies with astounding skill.' FROM games WHERE igdb_id = 264132 ON CONFLICT (game_id, language_code) DO NOTHING;
