INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eyeshield 21: Field no Saikyou Senshi-tachi', 'Eyeshield 21: Field Saikyou no Senshi Tachi, translated as Eyeshield 21: The Field''s Greatest Warriors in English, is a Nintendo published game released exclusively in Japan in March of 2007. The game is described by GameSpot as a "glimpse into how the Japanese view American football". It alters the rules, adds in Japanese styled Manga characters, and is overall one of the strangest football games ever released. The game stars Sena Kobayakawa, a small person who is great at playing American football.' FROM games WHERE igdb_id = 72994 ON CONFLICT (game_id, language_code) DO NOTHING;
