INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hooked! Real Motion Fishing', 'Enjoy the thrill of catching fish without the mess of cleaning them! With this unique Wii fishing game, the Wii Remote and Nunchuk controllers will allow players to relive all the excitement and tension of fishing in the comfort of their own living room. Explore 6 photorealistic lakes, from a meteorite crater turned lake to a man-made recreational reservoir.' FROM games WHERE igdb_id = 4914 ON CONFLICT (game_id, language_code) DO NOTHING;
