INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skate Attack', 'Your best skating buddy has been kidnapped and only you can save them! Use your boarding talent, zipping between hover cars, grinding rails and pulling sick trick combos! Hidden bonuses, pickups, a grappling laser, and your trusty stakeboard are everything you need to smack down your nemesis, ''virus'', and restore peace to the city! - 6 playable skaters to unlock, each with customised skills. - Huge environments to explore; from bustling ''Old Downtown'' and ''City Rooftop'' to the treacherous ''Waste Factory''. - Tutorial mode; get the heads up on tricks, manuals and pick ups. - Countless side missions, races, secret, areas and more! - Superb Multiplayer modes allow for tense, 2 player skate-offs!' FROM games WHERE igdb_id = 43524 ON CONFLICT (game_id, language_code) DO NOTHING;
