INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diddy Kong Racing DS: Timber''s Balloon Pop', 'Diddy Kong Racing DS: Timber''s Balloon Pop was an online Flash-powered advergame released by Nintendo to promote Diddy Kong Racing DS. It was listed along with other Nintendo-related web advergames in the Nintendo Arcade section of Nintendo''s official website. The player takes control of Timber, with Diddy Kong himself only making a cameo in the introductory screen. A mugshot of Wizpig is used as the game''s icon in the Nintendo Arcade, though he is not present in the game.' FROM games WHERE igdb_id = 231630 ON CONFLICT (game_id, language_code) DO NOTHING;
