INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Balloonacy!', 'BALLOONACY! vous invite à vivre le destin d''un petit ballon qui cherche désespérément à s''échapper par la fenêtre de salles aux couloirs tortueux et infestés de monstres. Votre ballon cherche naturellement à s''envoler, vous obligeant à le tirer continuellement vers le bas. Au moindre contact, c''est l''explosion. Évidemment, il faudra vous glisser dans les recoins les plus étroits pour aller actionner l''interrupteur du champ de force protégeant chaque fenêtre.' FROM games WHERE igdb_id = 39043 ON CONFLICT (game_id, language_code) DO NOTHING;
