INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Soukou Kihei Gun Ground', 'Pilot a fully customizable mech suit in this side scrolling action game. You can swap parts and add upgrades to make your mech suit unique to you! This game features random level generation and a branching story that makes for tons of replay value! You''ll never play through the same game twice! There is also a multiplayer versus mode in which up to 4 players can connect wirelessly and battle it out using just one cartridge! This game is a must own for any fans of the Mobile Suit Gundam series or any other mech related games or anime' FROM games WHERE igdb_id = 47837 ON CONFLICT (game_id, language_code) DO NOTHING;
