INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escape 2: The Closet', 'In this point and click adventure game, explore every inch of the closet in an attempt to find anything that might help you escape. Every item and every clue will have some kind of use, and it’s up to you to discover just what this use is, and how exactly to go about solving the game’s puzzles in your attempt to escape the closet.' FROM games WHERE igdb_id = 317400 ON CONFLICT (game_id, language_code) DO NOTHING;
