INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure II', 'Adventure II is a homebrew for the Atari 5200 programmed by Ron Lloyd and Alan Davis, with graphics by Keith Erickson. AtariAge began producing cartridges for the game in 2007. The Enchanted Chalice is once again missing, and it''s the player''s mission to return it to the Seashore Kingdom''s Castle, navigating through several mazes and kingdoms, and avoiding three dragons, a minotaur and a troll.' FROM games WHERE igdb_id = 284228 ON CONFLICT (game_id, language_code) DO NOTHING;
