INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Azteca', 'Azteca is a captivating puzzle game that challenges your strategic thinking and precision as you match and burst vibrant bubbles in a mesmerizing Aztec-themed setting. Immerse yourself in the rich tapestry of ancient civilizations while navigating through intricate levels filled with colorful orbs, each pop bringing you closer to unlocking the secrets of the Aztecs.' FROM games WHERE igdb_id = 206013 ON CONFLICT (game_id, language_code) DO NOTHING;
