INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pirates of the Seven Seas', 'If you are fascinated by the world of pirates and have always dreamed of crossing swords and emptying your pistol into a horde of bloodthirsty, wild enemies, Pirates of the Seven Seas is the must-have game for your mobile phone. Once downloaded, a fabulous adventure awaits you on your phone, where you''ll get to play a reckless pirate braving the greatest dangers on the hunt for a lost treasure. In the jungle, on a boat, in the pirate town, or on an antique surfboard, you''ll also get the chance to free the sexiest prisoners along the way!' FROM games WHERE igdb_id = 264256 ON CONFLICT (game_id, language_code) DO NOTHING;
