INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quadradius', 'Quadradius is an intricate and competitive game of skill, chance, bluffing, and devastation. It is a turn-based board game played by 1 to 6 people on a three dimensional grid. Each piece can collect Power Orbs scattered throughout the arena, these orbs contain one of over 30 versatile powers that can be unleashed to attack, defend, foil your opponent''s plans, or be combined together for even greater devastating effects.' FROM games WHERE igdb_id = 29040 ON CONFLICT (game_id, language_code) DO NOTHING;
