INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sporcle', 'Sporcle brings the wildly popular and addictive trivia quiz website Sporcle.com to your iPhone/iPod touch and iPad! No matter what your interest -- be it sports, movies, television, music, geography, and more – you can find hours of trivia entertainment. The app downloads new quizzes every day – just launch the app to test your skills against Sporcle’s latest brain-teasing challenges. Sporcle is the fun way to kill some time or procrastinate while exercising your brain. You just might even learn a thing or two!' FROM games WHERE igdb_id = 86844 ON CONFLICT (game_id, language_code) DO NOTHING;
