INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cake Mania 2', 'After re-opening the Evans Bakery, and sending her grandparents on an exotic Hawaiian cruise, Jill is back in an all-new, out-of-this-world series of adventures! Help Jill’s college friend Risha in her posh, northwestern, rooftop bakery; rescue her old flame, Jack, in his underwater theme park located on the ocean floor, or wind up in 4 other far-flung bakery locations, each with its own unique layout! What awaits Jill? Fame? Fortune? Love? In Cake Mania 2, you choose which path Jill pursues, with each decision leading to new baking challenges and dilemmas. With 204 levels of baking and frosting madness, 6 different possible endings and a branching, non-linear storyline, it’s your decision to make in Cake Mania 2!' FROM games WHERE igdb_id = 15045 ON CONFLICT (game_id, language_code) DO NOTHING;
