INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trism', 'Trism is a puzzle game for the Apple iPhone developed by Demiforce LLC. The game and developer made the news for being a rags to riches story. The game makes use of the iPhone''s built in accelerometer, and involves the sliding of colored triangular tiles called "trisms" in order to make matches of three or more. As soon as a match is made, the tiles disappear and, depending on the direction in which the iPhone is tilted, the gaps left behind will be filled.' FROM games WHERE igdb_id = 29043 ON CONFLICT (game_id, language_code) DO NOTHING;
