INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pirates Of The Caribbean: Islands Of Fortune', 'The game includes fifteen islands, each with three different mini-games. The player gets to control a cannon, search for treasure, and engage in sword fights. Beating one of these mini-games awards you gold. If you complete all three mini-games on the island, you conquer it. When you''re not on an island, you can sail freely and sink enemy ships to earn even more gold.' FROM games WHERE igdb_id = 294649 ON CONFLICT (game_id, language_code) DO NOTHING;
