INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CaveMan Rock', 'Caveman Rock was a puzzle game designed for PlayStation 2, Wii, Nintendo DS, and PC. Only the PS2 version was ever released. This prehistory themed game is easily described as Bust-A-Move or Puzzle Bubble, but upside down. Instead of popping bubbles by shooting the colored bubbles upwards, you destroy rising rocks by dropping down the colored rocks. You can also earn money that can be used to upgrade your companions that can help you along the way.' FROM games WHERE igdb_id = 43504 ON CONFLICT (game_id, language_code) DO NOTHING;
