INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clever Kids: Dino Land', 'Clever Kids: Dino Land is a compilation of six prehistoric themed games aimed at a younger audience. Sprocket the robot guides the player through the games which range from putting together a dinosaur puzzle to using movement cards to guide a dinosaur through a maze. Along the way various bits of interesting trivia about dinosaurs is displayed on screen.' FROM games WHERE igdb_id = 52504 ON CONFLICT (game_id, language_code) DO NOTHING;
