INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Countdown 2: The Soul', 'Countdown 2 - The Soul is the second of a trilogy of text adventure games released as a prequel, of sorts, to 6 Days a Sacrifice. Many of the events depicted expand on events in Trilby''s Notes or 6 Days a Sacrifice. You are a new acolyte in the Order of Blessed Agonies. You have already purged your body and mind. Now you must purge your soul by killing your boyfriend Jason. The nightmares from that day still haunt you. You wander out of the women''s dormitory and end up in the courtyard, where you meet a stranger in a tattered red robe. He has a task for you.' FROM games WHERE igdb_id = 229148 ON CONFLICT (game_id, language_code) DO NOTHING;
