INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sims DJ', 'Get into the groove with The Sims DJ! Create your Sim and make your own music by mixing a wide selection of samples in this great Sims game. Compose unique songs in multiple genres. Watch the Sims crowds dance to your best beats on your fun journey to DJ superstardom. Share your new tunes with your friends - create ringtones from your original songs and save to your phone!' FROM games WHERE igdb_id = 67879 ON CONFLICT (game_id, language_code) DO NOTHING;
