INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where''s an Egg?', 'In this hard-bolied adventure game, you must help the Boise police force find a missing egg. Not in Mancuso''s garage? Try Brodermaker''s gymbag. Everyone''s a suspect when "Where''s an Egg?" is the game that you are playing. And that''s this game!!' FROM games WHERE igdb_id = 135870 ON CONFLICT (game_id, language_code) DO NOTHING;
