INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fractal Fighter', 'Fractal Fighter is a shooting game, where the player''s spaceship engages several large enemy ships in one-on-one combat. The enemy ships resemble a branching fractal; they are made of a core, out of which branch out several large lasers; out of the tip of every laser branch out several heat-seeking missile launchers, which further branch out into triple guns, and finally small weak guns.' FROM games WHERE igdb_id = 185751 ON CONFLICT (game_id, language_code) DO NOTHING;
