INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nodame Cantabile', 'Based on the manga and anime of the same name, Nodame Cantabile follows the odd couple of Shinichi Chiaki and Megumi Noda. Both are students at the prestigious Momogaoka College of Music; Shinichi is a studious and strict conductor while Megumi is a pianist known for her loose and inventive playing style.' FROM games WHERE igdb_id = 285193 ON CONFLICT (game_id, language_code) DO NOTHING;
