INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('toyshop-trouble', 40608, '2007-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5yne.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toyshop Trouble', 'Ah, the Bahamas. Toyshop elves Patrick, Quincy, and Robert are laying on the beach, relaxing in the sun. Nothing could be finer than listening to the surf while enjoying a cold drink. A great reward for having gotten all of Santa''s toys painted in record time. Unfortunately for you, Patrick''s idea of "painting" toys was dumping them all in a bucket of gray paint. While this technically fulfilled his associates'' obligations (thus their trip to the Bahamas), the toys--alas--still have to be painted properly. It''s now your job to clean up their mess, which means properly painting the toys in time for Santa''s departure Christmas Eve. You must paint the toys as they move along five conveyor belts. Ahh, but only if it were as easy as it sounds! Toys must be painted the proper color, and some toys require two coats of paint (with different colors), and if that wasn''t bad enough, some must have their coats applied in the proper order! And not that you needed the additional pressure, but you also have a daily quota to meet. You must properly paint all the toys that appear on the conveyor belts each day before the whistle at the end of your shift sounds! Santa''s counting on you to ensure that all the toys are painted correctly! Can you get the job done before Santa''s sleigh is loaded up on Christmas Eve? You don''t want to be responsible for children waking up Christmas morning without toys under their trees, do you? Time to juggle those cans of paint and get moving!' FROM games WHERE igdb_id = 40608 ON CONFLICT (game_id, language_code) DO NOTHING;
