INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EyeToy Play: Astro Zoo', 'A huge space comet made the Astro Zoo spin out of its orbit and sent the Jungle Pod, Polar Dome, Woodland Hub and Marine Bubble into a great big cosmic muddle! As the Space Zookeeper, it’s up to you to round up your animal friends and put everything right again – in time for tomorrow’s grand opening! Using your EyeToy Camera, players can engage in games include helping the animals find their spacesuits, going deep space sheep-shearing and herding the crocs back into their Astro tank!' FROM games WHERE igdb_id = 43211 ON CONFLICT (game_id, language_code) DO NOTHING;
