INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monopoly: SpongeBob SquarePants Edition', 'Wheel and deal your way through Bikini Bottom in the PC game that takes the board game to whole new levels of interactive excitement. Play as one of your favorite SpongeBob Characters - SpongeBob, Patrick, Sandy or Squidward with up to four players at the same time. Four modes of play - Classic, SpongeBob, Squidward and Plankton 14 addictive minigames! Like. Bargain Battle - Quick click action gets the best price for the property Pump Panic - Oh barnacles! Your Utility rent will be determined by the water level in the pool!' FROM games WHERE igdb_id = 68109 ON CONFLICT (game_id, language_code) DO NOTHING;
