INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pac-Motos', 'The player controls Pac-Man and must knock all of the enemies off of the stage in order to complete the level, much like the original Motos. The player must traverse through five different worlds, each comprised of seven stages. The seventh stage features a boss piloted by either member of the Ghost Gang and must be defeated in order to proceed to the next world.' FROM games WHERE igdb_id = 203273 ON CONFLICT (game_id, language_code) DO NOTHING;
