INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob Diner Dash 2: Two Times the Trouble', 'Developed and published by PlayFirst in 2007 for PC, this time management game has players help SpongeBob and friends save their favorite restaurants from Sharkey Two-Times, who plans to open a casino in Bikini Bottom. The game features new characters, challenges, power-ups, and restaurants while maintaining the classic Diner Dash gameplay style.' FROM games WHERE igdb_id = 208781 ON CONFLICT (game_id, language_code) DO NOTHING;
