INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Geometry Wars: Waves', 'Geometry Wars: Waves was developed by Stephen Cakebread of Bizarre Creations, released as a bonus mini-game as part of Project Gotham Racing 4 on Xbox 360. The game is a variant of Geometry Wars: Retro Evolved where the player is given one life to survive continual waves of orange rockets that pace back and forth across the edges of the play-field for as long as possible.' FROM games WHERE igdb_id = 4886 ON CONFLICT (game_id, language_code) DO NOTHING;
