INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Rangers 2: Reboot', 'It''s an official remake of the "Space Rangers 2: Dominators". This edition contains the original "Space Rangers" (2002) and the improved version of the "Space Rangers 2: Dominators" (2004). Among the new features are new game modes, new spaceship screen, new spaceship types, new equipment with additional characteristics, new text quests and new maps. This edition also contains a lot of fan art - mini-games, pictures, wallpapers and screensavers. Many "Space Rangers" fans from the official game forum actively contributed to this remake - they created maps, wrote quests and tested the game.' FROM games WHERE igdb_id = 208846 ON CONFLICT (game_id, language_code) DO NOTHING;
