INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hard Knock High', 'Rise to power as "Gripper" Hard Knock High''s gang leader. Be the toghest thug in the Neighbourhood! Start off fighting in your own school to build up your skills. Master cool fighting styles! Fight your opponents with cool styles like Karate, Boxing, Judo and more... Put Gripper through an assortment of mini-games to strengthen him!' FROM games WHERE igdb_id = 43350 ON CONFLICT (game_id, language_code) DO NOTHING;
