INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Football ''08', 'Backyard Football ''08 is the sixth iteration of the best selling children''s football video game. The only kids'' game to hold the NFL and NFL Player''s Inc. licenses, Backyard Football ''08 features a roster full of current NFL Superstars as kids including two-time SuperBowl MVP Tom Brady as the cover/highlight athlete. Backyard Football ''08 combines authentic NFL plays and strategies with the wild and whacky antics of the Backyard gang to give young football fans a realistic, fun sports experience. The game gives kids total control of the style, location, pace, and strategy. And, with multiple levels, is easy enough for rookie players yet mega challenging for more seasoned veterans.' FROM games WHERE igdb_id = 43208 ON CONFLICT (game_id, language_code) DO NOTHING;
