INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '5 Realms of Cards', '5 Realms of Cards interweaves a revolutionary new solitaire gameplay with a fairy-tale story. Explore over 70 levels to help a young princess named Jokerine restore peace and beauty in card realms and learn a secret! Use cool bonuses to make your way through 5 unique card realms. Play 5 card-based mini-games and explore a beautifully rendered world in 5 Realms of Cards.' FROM games WHERE igdb_id = 52353 ON CONFLICT (game_id, language_code) DO NOTHING;
