INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Charlie Foxtrot & The Galaxy of Tomorrow', 'A rebel clone meets a zany galaxy in this high-intensity sci-fi parody. Hundreds of animations, spectacular humour, full sound-track and a bunny''s lair worth of easter eggs make this game a must play! You play Charlie Foxtrot, a clone who rebels against conformity. Undertaking an intergalactic quest so that he can assert his autonomy, Charlie travels to strange planets inhabited by dozens of parodied sci-fi characters. The humour is somewhere between Space Quest and Red Dwarf, but the adventure is beyond comparison.' FROM games WHERE igdb_id = 166692 ON CONFLICT (game_id, language_code) DO NOTHING;
