INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Europa Universalis III: Collector''s Edition', 'This collector''s edition contains the following: - Europa Universalis III - Audio disc with the game''s soundtrack - Composer''s diary, complementing the soundtrack - Full-colour strategy guide of more than 100 pages - Producer introduction to the game - Exclusive download content - Sizable poster map including all provinces. - Collectible stickers' FROM games WHERE igdb_id = 52971 ON CONFLICT (game_id, language_code) DO NOTHING;
