INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Instinct', 'Instinct is a story-driven first person shooter inspired by real-life events in a mountainous region of North Korea. An elite U.S. Army unit is stranded on a top-secret Korean military installation. The aftermath of the operation crossed the world news flashes on September 9, 2004.  Take the role of one of three playable characters in this first person shooter that delivers horror, action, and drama as you uncover the reasons behind the massive viral infection' FROM games WHERE igdb_id = 27548 ON CONFLICT (game_id, language_code) DO NOTHING;
