INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paws & Claws: Dogs & Cats Best Friends', 'In "My Best Friends: Dogs & Cats," you have the unique opportunity to play with and cuddle Dalmatian, Husky, German Shepherd and Retriever puppies and Siamese, Maine Coon, British Blue and Domestic cats. Teach them lots of crazy tricks, and form a team that will win prizes both in the beauty contests and the obstacle course competitions. Train to perfection and become best friends!' FROM games WHERE igdb_id = 47893 ON CONFLICT (game_id, language_code) DO NOTHING;
