INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elvandia Story', 'The story revolves around Ashley, son of a Lord from the State of Kastol, who recently returned to his home town. While he is with his friends, he receives a message that the neighbouring State of Lumen is under attack from the north by the troops of Genes. He decides to stop Genes and starts his journey to Lumen in order to end the fight and restore peace on the continent.' FROM games WHERE igdb_id = 43276 ON CONFLICT (game_id, language_code) DO NOTHING;
