INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Ages 2500 Vol. 31: Cyber Troopers Virtual-On', 'This game is an update to the arcade version of Cyber Troopers Virtual-On. It features a variety of extra options such as widescreen support, system link, "assault mode" (removing projectile weapons) and "chibi mode" (similar to Virtua Fighter Kids). You can also play as the final boss in "Z-Gradt mode", and can enable "dash cancelling", a feature introduced in Cyber Troopers Virtual-On: Oratorio Tangram.' FROM games WHERE igdb_id = 140085 ON CONFLICT (game_id, language_code) DO NOTHING;
