INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('game-game-game-and-again-game', 231840, '2007-04-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co60ss.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game, Game, Game, and again Game', 'Game, game, game and again game is a digital poem, retro-game, an anti-design statement and a personal exploration of the artist''s changing worldview lens. Much of the western world''s cultural surroundings, belief systems, and design-scapes, create the built illusion of clean lines and definitive choice, cold narrow pathways of five colors, three body sizes and encapsulated philosophy. Within net/new media art the techno-filter extends these straight lines into exacting geometries and smooth bit rates, the personal as WYSIWYG buttons. This game/artwork, while forever attached to these belief/design systems, attempts to re-introduce the hand-drawn, the messy and illogical, the human and personal creation into the digital, via a retro-game style interface, Hovering above and attached to the poorly drawn aesthetic is a personal examination of how we/I continually switch and un-switch our dominant belief systems. Moving from levels themed for faith or real estate, for chemistry or capitalism, the user triggers corrected poetry, jittering creatures and death and deathless noises. In addition each level contains short videos from the artist''s childhood, representing those brief young interactions which spark out eventual beliefs. Game, game, game and again game is less a game about scoring and skill, and more an awkward and disjointed atmospheric, the self built into a jumping, rolling meander of life.' FROM games WHERE igdb_id = 231840 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 231840 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
