INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Frog Arcade Racer', 'The Crazy Frog is cranking up the speed for his latest and greatest racing adventure! After winning the cup and escaping the Drone, the Crazy Frog is now ready to shift into the next gear for the craziest race ever! With more speed, zanier power-ups, new friends and even more insane tracks, there is no stopping the Crazy Frog this time! Race through the popular music videos of the Crazy Frog world and use even more zany power ups to ba-ding ding the competition.' FROM games WHERE igdb_id = 43226 ON CONFLICT (game_id, language_code) DO NOTHING;
