INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brian Lara 2007 Pressure Play', 'Brian Lara 2007 Pressure Play is the first PSP incarnation of the Codemasters series of Brian Lara cricket games. It has simple controls and an arcade feel. Gameplay largely involves pressing a button at the right time to hit a shot, take a catch, return a throw, and bowl a good delivery.' FROM games WHERE igdb_id = 70025 ON CONFLICT (game_id, language_code) DO NOTHING;
