INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil Summoner: Soul Hackers Intruder', 'Soul Hackers Intruder is a strategy RPG based on Devil Summoner: Soul Hackers. It takes place half a year after the events of the original game. New enemies appear in Amami City and Spookies reunite. Action is divided between story and battle sections, with the battle sections being turn-based strategy style fights. This game also introduces a capacity system that demons can activate once per battle.' FROM games WHERE igdb_id = 139069 ON CONFLICT (game_id, language_code) DO NOTHING;
