INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demon King Chronicle', 'There once was a book called “The Story of the Demon King.” The book had no ending. This is an indie RPG with very few cutscenes, but with a fair amount of freedom and a healthy portion of difficulty. Level up steadily. Focus on attack power and rush at the enemy, ready to die honorably. Play the game the way you want to, and bring this story to an end.' FROM games WHERE igdb_id = 145345 ON CONFLICT (game_id, language_code) DO NOTHING;
