INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oddnose', 'Nasty and unfriendly clowns have invaded the forest of a funny animal named Oddnose, and now he needs to get rid of them. Cast the balls with your nose and use it and them as weapons. Eat beans with it, thereby causing the gas attack,push off the ground or eat a chili pepper - the effect is impressive. Do your best to get rid of the hated colorful clowns.' FROM games WHERE igdb_id = 247351 ON CONFLICT (game_id, language_code) DO NOTHING;
