INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hold ''Em', 'Hold ''Em (formerly Windows Poker as in build 5284) is a poker card game released on January 29, 2007 that is fundamentally similar to Texas hold ''em. Hold ''Em allows users to play against up to five computer players and up to three levels of difficulty, and also allows users to customize aspects of the game''s appearance; the game relies on DirectX to produce hardware-accelerated 3D animations and effects.' FROM games WHERE igdb_id = 241668 ON CONFLICT (game_id, language_code) DO NOTHING;
