INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris Diamond', 'A new technique that makes full use of "diamond block" is now available! There are 4 game modes of "TETRIS DIAMOND": "TETRIS", "DIAMOND", "DIA.2min" and "PUZZLE". In the new mode "DIAMOND" and "DIA.2min", a "diamond block" appears for every 5 falling tetriminoes, and if you erase the line with this block, the score will be doubled. Get a BACK TO BACK bonus by making full use of "TETRIS", "T-SPIN" and the new technique "DIAMOND" that erases using diamond blocks! Please keep updating the record of high score!!' FROM games WHERE igdb_id = 152167 ON CONFLICT (game_id, language_code) DO NOTHING;
