INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hoshi Saga', 'Hoshi Saga is a simple game of discovery. One part point-and-click and one part puzzle game, the objective in each of the game''s 36 stages is to find the star. How you go about doing that is different for every stage. The task is up to you to figure out how.' FROM games WHERE igdb_id = 100678 ON CONFLICT (game_id, language_code) DO NOTHING;
