INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hot-brain', 44483, '2007-06-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co723d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsrx0.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hot Brain', 'Fire up your mind with Hot Brain, a game that engages the mind through a series of puzzles and challenges designed to raise the activity and temperature of your brain. Hot Brain presents challenging and fun mental activities that help ignite your mind in areas like logic, memory, math, language and concentration. Exclusive to the PSP system, the game allows you to test your skills in several single player modes or you can play with up to three people via ad-hoc connection. Fire up your mind with four main game modes including two multiplayer modes (Brain Race and Think Tank) and two single player modes (Test Mode and Practice). Whether you''re an expert or a beginner, a robust tutorial mode makes the game accessible and enjoyable to people of all ages.' FROM games WHERE igdb_id = 44483 ON CONFLICT (game_id, language_code) DO NOTHING;
