INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1500 DS Spirits Vol. 3: Block Kuzushi', '1500DS Spirits Vol. 3: Block Kuzushi is an Action game, modelled after the classic game Breakout, developed and published by Tasuke, which was released in Japan in 2007. This game is a simple and straightforward game in which the player controls a board to play balls and break the blocks in the screen. There are various stages with different arrangements of blocks, but can the player really clear all the stages?' FROM games WHERE igdb_id = 69129 ON CONFLICT (game_id, language_code) DO NOTHING;
