INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Platform Racing', 'Platform Racing (commonly abbreviated PR1) is a 2007 online multiplayer racing Flash game that was developed by Jacob Grahn. Its premise was inspired by Mario Kart, with him setting out to create a sidescrolling platformer spin on its formula.' FROM games WHERE igdb_id = 270638 ON CONFLICT (game_id, language_code) DO NOTHING;
