INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi Connection V5 Familitchi', 'The Tamagotchi Connection Version 5 "Familitchi" is the sixth model in the line of Tamagotchi Connection virtual pets. The Japanese edition was released on November 23, 2007, and globally as the V5 Familitchi in January 2008. Unlike the previous Tamagotchi Connection releases after the V1, the V5 is a functionally identical to its Japanese counterpart. A new feature is that you can raise Tamagotchi Families, with up to 3 kids, and on Generation 2 or higher, two parents.' FROM games WHERE igdb_id = 229954 ON CONFLICT (game_id, language_code) DO NOTHING;
