INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bob the Builder', 'Bob the Builder is a licensed PS2 game that uses characters and art from the popular UK children TV show ''Bob the Builder''. The game was released bundled with the Eye Toy and it is central to game play. In between clips from the tv show the player hits on screen buttons via the motion control to play. For example hitting left right or jump to navigate an ATV down a country road. Cleaning the vehicles by waving your arms over their on screen position, and nailing sawing and drilling by similar methods.' FROM games WHERE igdb_id = 269369 ON CONFLICT (game_id, language_code) DO NOTHING;
