INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sengoku Gensokyo', 'Being a parody beetwen the Rance and Touhou series, the story sets the player as Hakurei Reimu into a situation where Gensoukyou has been divided up into various warring states. The ever mischievous Yakumo Yukari, the culprit behind the start of this war game, has sent out letters to all of the major factions of the world laying out the rules of the game and promising to grant one wish for the winning team.' FROM games WHERE igdb_id = 299300 ON CONFLICT (game_id, language_code) DO NOTHING;
