INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Studio 100', 'SingStar: Studio 100 is a karaoke game exclusively released in the Netherlands. It includes songs from Studio 100''s children''s TV shows. There are no changes to the gameplay formula: player(s) sing into a microphone and the game gives points based on the performance. The only basis of assessment is if the correct note is hit with the correct timing; the sung words or octave does not play into the result.' FROM games WHERE igdb_id = 45301 ON CONFLICT (game_id, language_code) DO NOTHING;
