INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Might and Magic Mobile II', 'Might and Magic Mobile II is a role-playing video game developed and released by Gameloft for mobile phones (Java ME platform). It is a prequel to the original Might and Magic Mobile. Like its predecessor, it does not follow the continuity of the core Might and Magic series. This game is based on a castle storm in which you take many roles. The game was also reskinned with a modified story and setting without the Might and Magic license and released on the Nintendo DSi under the name Legends of Exidia.' FROM games WHERE igdb_id = 315321 ON CONFLICT (game_id, language_code) DO NOTHING;
