INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Onsei Kanjou Sokuteiki: Kokoro Scan', 'While all games from Sega''s Naruhodo edutainment series did not garner much mention, this game did. This is due to its bizzare premise and unique use of the Nintendo DS microphone picking up nuances in emotions of the voice. This technology was developed by SGI Japan.' FROM games WHERE igdb_id = 314324 ON CONFLICT (game_id, language_code) DO NOTHING;
