INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DS Kageyama Method: Tadashii Kanji Kakitori-Kun - Kondo ha Kanken Taisaku Dayo!', 'An educative program on Nintendo DS to learn writing and pronouncing kana and kanji signs of the Japanese language. This is an addition of the Tadashii Kanji series that includes all 1945 jouyou kanji. It teaches readings, meanings, and vocabulary making it a very good game to learn kanji.' FROM games WHERE igdb_id = 98806 ON CONFLICT (game_id, language_code) DO NOTHING;
