INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clive Barker''s Jericho: Special Edition', 'Sometimes referred to as simply Jericho, is a first person shooter survival horror video game with author Clive Barker providing the premise of the storyline. Jericho''s core gameplay consists of leading the game''s seven-man team codenamed Jericho, allowing control of all team members by jumping to each character during certain points in the game, through various environments that have been warped by the Firstborn while fighting off a variety of twisted creatures.' FROM games WHERE igdb_id = 47470 ON CONFLICT (game_id, language_code) DO NOTHING;
