INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucky Coins', 'Lucky Coins is a bumping fun mix of the best elements of Pinball, Pachinko and Arcades! Feeling lucky? Drop the golden coin and let it bounce off bumpers, pins and moving gizmos. Magnets will trap the coin and allow you to set new aim and blast away the coin in your desired direction.' FROM games WHERE igdb_id = 175264 ON CONFLICT (game_id, language_code) DO NOTHING;
