INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soup', 'Soup ver 0.9 is a production loosely based on LSD, a trippy dream recollection available only on the Playstation console. Choose the first option to play in full screen mode. A different part of the adventure is unlocked for each new game attempted by the player. Hold the left shift key to look around, and touch a wall to exit any room. Describing the game any further is equivalent to providing possible spoilers.' FROM games WHERE igdb_id = 188612 ON CONFLICT (game_id, language_code) DO NOTHING;
