INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DJMax Portable 2', 'DJ Max Portable 2 introduces one more gameplay mode and offers a song selection of more than 60 tunes. In the new Fever Mode, you fill up your Fever ability which, when activated, speeds up the notes and applies a 2x score multiplier. By filling up yet another Fever, you can activate it again for a 3x multiplier, so on and so forth.' FROM games WHERE igdb_id = 42724 ON CONFLICT (game_id, language_code) DO NOTHING;
