INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'John Tiller''s Campaign Series', 'The John Tiller''s Campaign Series exemplifies tactical war-gaming at its finest by bringing you the entire collection of TalonSoft''s award-winning campaign series. Containing TalonSoft''s West Front, East Front, and Rising Sun platoon-level combat series, as well as all of the official add-ons and expansion packs, the Matrix Edition allows players to dictate the events of World War II from the tumultuous beginning to its climatic conclusion.' FROM games WHERE igdb_id = 129544 ON CONFLICT (game_id, language_code) DO NOTHING;
