INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Petz: Dogz 2', 'Pick a puppy pal from a pack of fuzzy and adorable puppies in Petz Dogz 2! Together, you and your new cuddly companion will encounter a world that’s fun to play in, explore, and share. Dress up your puppy in fun puppy clothes, play for hours with new toys, or look for hidden surprises that can give your puppy new abilities. Customize your puppy’s environment with items and toys, and unlock more goodies as you get better at caring for your new best friend. Watch your puppy grow, go on quests and adventures together, and unlock awesome mini-games.' FROM games WHERE igdb_id = 5094 ON CONFLICT (game_id, language_code) DO NOTHING;
