INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Trader', 'In the far future, humanity is ruled by The Ministry of Accounts, an oppressive bureaucracy that tracks, records and taxes every transaction of daily life. A new breed of marketeer arises to challenge the authority and make a profit: the Space Trader is born! As a Trader, you will attempt to amass a fortune, buying and selling commodities and taking up arms against the oppressors or even accepting bounty missions.' FROM games WHERE igdb_id = 9469 ON CONFLICT (game_id, language_code) DO NOTHING;
