INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cave Chaos', 'Cave Chaos is a platforming game created by Nitrome. You''re a miner whose goal is to escape a collapsing cave. Start running immediately and pick up the loot on your way before reaching the end of the level. Jump over the boxes swiftly but carefully to avoid falling alongside the rocks. Don''t forget to make use of the power-ups such as double-jump, invincibility and bombs. There is so much to explore in Starfish Cove. Play Cave Chaos with a friend to maximize the fun!' FROM games WHERE igdb_id = 250612 ON CONFLICT (game_id, language_code) DO NOTHING;
