INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Supercow', 'Check out this super-dynamic arcade game about the adventures of a new character that deserves everyone''s attention: Supercow! The evil professor Duriarti has escaped from the prison and captured the farm in Sunny Valley! Now he is creating an army of clones from innocent animals! While nobody knows exactly he’s plotting, the mad professor is continuing his evil experiments his cave-lab! And only Supercow can stop him!' FROM games WHERE igdb_id = 175553 ON CONFLICT (game_id, language_code) DO NOTHING;
