INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'JellyCar', 'JellyCar (originally titled “JelloCar”) is a driving/platforming game for both Windows and Xbox360. The game is about driving a squishy car through squishy worlds, trying to reach the exit. The game features soft body physics for all of the objects in the world. Also your car can transform for a limited time to aid progression through the level.' FROM games WHERE igdb_id = 95422 ON CONFLICT (game_id, language_code) DO NOTHING;
