INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virus Alert 3D', '"Weird Al" Yankovic is finally starring in his own video game - VIRUS ALERT! - based on the song from his latest album, Straight Outta Lynwood. It''s more fun than a warehouse full of pink leotards! Hoards of viruses have spread throughout the computer network of Company-Tech Co., Ltd., LCC, Al''s new employer. Help Al advance in his job by "deleting" the viruses and protecting machines from the spreading menace with antiviral CDs.' FROM games WHERE igdb_id = 320478 ON CONFLICT (game_id, language_code) DO NOTHING;
