INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Build-A-Bear Workshop', 'Get ready for the total Build-A-Bear experience on Nintendo DS! Make your own Build-A-Bear, dress it up, play with it in lots of funny activities and mini games! The Bear will be like a virtual extension of yourself and a personal companion you can love like a best friend. You must make sure you satisfy its daily needs as physical affection, fun, food, learning, social life and trendyness are all necessary elements for the Bear to be balanced and happy. A highly interactive and trans-generational game in the true Build-A-Bear spirit!' FROM games WHERE igdb_id = 47811 ON CONFLICT (game_id, language_code) DO NOTHING;
