INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pico Sim Date 2', 'Pico Sim Date 2 is a point-and-click Flash game co-created by Moosh and Acromatik for Pico Day, and released on May 1, 2007. It is the second entry in the Pico Sim Date series and acts as the direct sequel to Pico Sim Date. This time, Pico has to save the kidnapped Nene from the psychotic Cyclops, through dating four girls who have information on his whereabouts.' FROM games WHERE igdb_id = 276253 ON CONFLICT (game_id, language_code) DO NOTHING;
