INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yukkuri Tanoshimu Otona no Jigsaw Puzzle DS: Sekai no Meiga 1 - Renaissance, Baroque no Kyoshou', 'Yukkuri Tanoshimu Otona no Jigsaw Puzzle DS: Sekai no Meiga 1: Renaissance, Baroque no Kyoshou is a Puzzle game, developed and published by Interchannel, which was released in Japan in 2007. Players complete jigsaw puzzles of various sizes and challenge levels to reveal stunning works of classical artwork.' FROM games WHERE igdb_id = 124160 ON CONFLICT (game_id, language_code) DO NOTHING;
