INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'M.A.C.H', 'Welcome to the world of M.A.C.H. Modified Air Combat Heroes rise through the ranks by defeating rivals and unlocking customized parts and planes -- 180 over-the-top configurations possible across 11 planes -- for enhanced speed and weaponry. Gamers will take to the skies for intense aerial racing action and deadly air-to-air combat throughout a variety of environments and can choose from multiple gameplay modes.' FROM games WHERE igdb_id = 44508 ON CONFLICT (game_id, language_code) DO NOTHING;
