INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Close Combat: Cross of Iron', 'Close Combat: Cross of Iron is an enhanced remake of the critically acclaimed real time strategy game, Close Combat III: The Russian Front by Atomic Games. Playing as either the Germans or Russians, the game takes place during WWII on the Russian Front, where as a commander you must lead your troops through five years of brutal combat.' FROM games WHERE igdb_id = 63189 ON CONFLICT (game_id, language_code) DO NOTHING;
